import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Car,
  Star,
  HelpCircle,
  Settings,
  ChevronRight,
  LogOut,
  ShieldCheck,
  ShieldX,
  RotateCcw,
  User,
  Clock,
  ArrowRightLeft,
  Crown,
  Zap,
  MapPin,
  Wallet,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useOrder } from '@/lib/order-context';
import { useI18n } from '@/lib/i18n';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { toast } from 'sonner';
import { getDriverEarnings } from '@/lib/api';

export default function DriverProfilePage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const {
    driverVerified,
    driverApplication,
    resetDemoData,
    setDriverOnline,
    setCurrentRole,
    driverIsVvip,
    driverVvipExpiresAt,
    driverLevel,
    vvipApplied,
    submitVvipApplication,
    logout,
    user,
    isLoggedIn,
  } = useOrder();
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const [vvipSubmitting, setVvipSubmitting] = useState(false);
  const [realStats, setRealStats] = useState<{ orders: number; income: number }>({ orders: 0, income: 0 });

  // 登入守衛
  useEffect(() => {
    if (!isLoggedIn) {
      navigate('/driver/login', { replace: true });
    }
  }, [isLoggedIn, navigate]);

  // 攞真實訂單統計（總單數 + 總收入）
  useEffect(() => {
    getDriverEarnings()
      .then((orders: any[]) => {
        const list = Array.isArray(orders) ? orders : [];
        const income = list.reduce((s, o) => s + (Number(o.actualFare) || Number(o.estimatedFare) || 0), 0);
        setRealStats({ orders: list.length, income });
      })
      .catch(() => { /* 後端未通時保持 0 */ });
  }, []);

  const handleVvipApply = async () => {
    setVvipSubmitting(true);
    try {
      await submitVvipApplication();
      toast.success('皇牌申請已遞交');
    } catch {
      toast.error('提交失敗');
    } finally {
      setVvipSubmitting(false);
    }
  };

  const handleReset = () => {
    resetDemoData();
    setDriverOnline(false);
    toast.success('已重置示範數據');
    setShowResetConfirm(false);
  };

  const handleSwitchToPassenger = () => {
    setDriverOnline(false);
    setCurrentRole('passenger');
    navigate('/passenger');
  };

  const handleLogout = () => {
    setDriverOnline(false);
    logout();
    navigate('/');
  };

  const menuItems = [
    { icon: Car, label: '車輛資料', value: [user?.car_model, user?.plate].filter(Boolean).join(' · ') || '未填寫', onClick: () => navigate('/driver/settings') },
    { icon: Star, label: t.driverProfile.menuRating, value: (user?.rating ?? 4.8).toFixed(1), onClick: () => navigate('/driver/rating-list') },
    { icon: Wallet, label: '錢包 / 提現', value: '', onClick: () => navigate('/driver/wallet') },
    { icon: HelpCircle, label: '幫助中心', value: '', onClick: () => navigate('/driver/help') },
    { icon: Settings, label: '設定', value: '', onClick: () => navigate('/driver/settings') },
  ];

  return (
    <div className="min-h-screen bg-black text-white flex flex-col pb-28">
      {/* 頂部頭像區 */}
      <div className="bg-gradient-to-br from-yellow-600 via-yellow-700 to-yellow-800 text-white px-5 pt-8 pb-20 rounded-b-[2rem]">
        <div className="flex items-center gap-4">
          <div className="size-20 rounded-full bg-black/20 flex items-center justify-center border-4 border-white/20">
            <User className="size-10 text-white/90" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <h1 className="text-2xl font-black">{user?.name || '司機'}</h1>
              {driverIsVvip && (
                <span className="px-2 py-0.5 rounded-full bg-white/25 text-white text-xs font-bold">
                  👑 皇牌
                </span>
              )}
            </div>
            <p className="text-base text-yellow-100 mt-1 font-mono">
              {user?.username || ''}
              {user?.phone && ` · ${user.phone}`}
            </p>
          </div>
          <button
            className="size-11 rounded-full bg-white/20 flex items-center justify-center hover:bg-white/30 transition-colors"
            aria-label="設定"
          >
            <Settings className="size-6 text-white" />
          </button>
        </div>
      </div>

      {/* 數據大字卡 - 浮起 */}
      <div className="px-4 -mt-12">
        <div className="rounded-2xl bg-zinc-900 border border-zinc-700 shadow-xl p-5 grid grid-cols-3 divide-x divide-zinc-700">
          <div className="text-center px-1">
            <div className="text-3xl font-black text-white tabular-nums">{realStats.orders}</div>
            <div className="text-sm text-zinc-400 mt-1">總單數</div>
          </div>
          <div className="text-center px-1">
            <div className="text-3xl font-black text-yellow-400 tabular-nums">{realStats.income ? `HK$${realStats.income.toLocaleString()}` : 'HK$0'}</div>
            <div className="text-sm text-zinc-400 mt-1">總收入</div>
          </div>
          <div className="text-center px-1">
            <div className="text-3xl font-black text-yellow-400 tabular-nums">{(user?.rating ?? 4.8)?.toFixed?.(1) ?? '4.8'}</div>
            <div className="text-sm text-zinc-400 mt-1">評分</div>
          </div>
        </div>
      </div>

      {/* 帳號狀態 */}
      <div className="px-4 mt-5">
        {user?.status === 'approved' ? (
          <div className="rounded-2xl bg-green-500/10 border border-green-500/30 p-4 flex items-center gap-4">
            <div className="size-14 rounded-xl bg-green-500/20 flex items-center justify-center shrink-0">
              <ShieldCheck className="size-7 text-green-400" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-lg font-bold text-white">{t.driverProfile.verifiedDriver}</div>
              <div className="text-sm text-green-400/80">{t.driverProfile.verifiedDesc}</div>
              {user?.phone && (
                <div className="text-xs text-zinc-400 mt-1 font-mono">
                  {user.username} · {user.phone}
                </div>
              )}
            </div>
          </div>
        ) : user?.status === 'pending' ? (
          <div className="rounded-2xl bg-yellow-500/10 border border-yellow-500/30 p-4 flex items-center gap-4">
            <div className="size-14 rounded-xl bg-yellow-500/20 flex items-center justify-center shrink-0">
              <Clock className="size-7 text-yellow-400 animate-pulse" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-lg font-bold text-white">{t.driverProfile.verifyPending}</div>
              <div className="text-sm text-yellow-400/80">{t.driverProfile.verifyPendingDesc}</div>
              <div className="text-xs text-yellow-400/60 mt-1">{t.driverProfile.verifyPendingTip}</div>
            </div>
          </div>
        ) : user?.status === 'rejected' ? (
          <div className="rounded-2xl bg-red-500/10 border border-red-500/30 p-4 flex items-center gap-4">
            <div className="size-14 rounded-xl bg-red-500/20 flex items-center justify-center shrink-0">
              <ShieldX className="size-7 text-red-400" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-lg font-bold text-white">{t.driverProfile.verifyRejected}</div>
              <div className="text-sm text-red-400/80">{t.driverProfile.verifyRejectedDesc}</div>
            </div>
          </div>
        ) : (
          <button
            onClick={() => navigate('/driver/verify-status')}
            className="w-full rounded-2xl bg-yellow-500/10 border border-yellow-500/30 p-4 flex items-center gap-4 hover:bg-yellow-500/15 transition-colors text-left"
          >
            <div className="size-14 rounded-xl bg-yellow-500/20 flex items-center justify-center shrink-0">
              <ShieldX className="size-7 text-yellow-400" />
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-lg font-bold text-white">{t.driverProfile.unverifiedStatus}</div>
              <div className="text-sm text-yellow-400/80">{t.driverProfile.unverifiedDesc}</div>
            </div>
            <ChevronRight className="size-5 text-yellow-400 shrink-0" />
          </button>
        )}
      </div>

      {/* 皇牌專區 */}
      {user?.status === 'approved' && (
        <div className="px-4 mt-4">
          {driverIsVvip ? (
            <div className="rounded-2xl bg-gradient-to-r from-blue-600/20 to-blue-500/10 border border-blue-500/30 p-4 flex items-center gap-4">
              <div className="size-14 rounded-xl bg-blue-500/20 flex items-center justify-center shrink-0">
                <Crown className="size-7 text-blue-400" fill="currentColor" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-lg font-bold text-white flex items-center gap-2">
                  皇牌特選司機
                </div>
                <div className="text-sm text-blue-400/80">優先派高質訂單 · 貼士更多</div>
                <div className="text-xs text-zinc-400 mt-1">
                  {driverVvipExpiresAt
                    ? `有效期至 ${new Date(driverVvipExpiresAt).toLocaleDateString('zh-HK')}`
                    : '皇牌（永久）'}
                </div>
              </div>
              <ChevronRight className="size-5 text-zinc-500 shrink-0" />
            </div>
          ) : vvipApplied ? (
            <div className="rounded-2xl bg-blue-500/10 border border-blue-500/30 p-4 flex items-center gap-4">
              <div className="size-14 rounded-xl bg-blue-500/20 flex items-center justify-center shrink-0">
                <Clock className="size-7 text-blue-400 animate-pulse" />
              </div>
              <div className="flex-1 min-w-0">
                  <div className="text-lg font-bold text-white">皇牌申請中</div>
                <div className="text-sm text-blue-400/80">工作人員會聯絡你</div>
              </div>
            </div>
          ) : (
            <button
              onClick={handleVvipApply}
              disabled={vvipSubmitting}
              className="w-full rounded-2xl bg-gradient-to-r from-blue-600/20 to-yellow-500/10 border border-blue-500/30 p-4 flex items-center gap-4 hover:from-blue-600/30 transition-colors text-left disabled:opacity-60"
            >
              <div className="size-14 rounded-xl bg-blue-500/20 flex items-center justify-center shrink-0">
                <Crown className="size-7 text-blue-400" />
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-lg font-bold text-white">
                  申請成為皇牌司機
                  {vvipSubmitting && <span className="text-xs text-zinc-400 ml-2">申請中...</span>}
                </div>
                <div className="text-sm text-blue-400/80">優先派單 · 賺更多錢</div>
              </div>
              <ChevronRight className="size-5 text-blue-400 shrink-0" />
            </button>
          )}
        </div>
      )}

      {/* 功能選單 */}
      <div className="px-4 mt-4">
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
          {menuItems.map((item, i) => {
            const Icon = item.icon;
            return (
              <button
                key={item.label}
                onClick={item.onClick}
                className={`w-full flex items-center gap-4 px-4 py-4 hover:bg-zinc-800/60 transition-colors text-left ${
                  i !== 0 ? 'border-t border-zinc-800' : ''
                }`}
              >
                <div className="size-11 rounded-xl bg-yellow-500/15 flex items-center justify-center shrink-0">
                  <Icon className="size-5 text-yellow-400" />
                </div>
                <span className="flex-1 text-lg font-bold text-white">
                  {item.label}
                </span>
                {item.value && (
                  <span className="text-base text-zinc-400 font-medium">
                    {item.value}
                  </span>
                )}
                <ChevronRight className="size-5 text-zinc-600 shrink-0" />
              </button>
            );
          })}
        </div>
      </div>

      {/* 切換角色 */}
      <div className="px-4 mt-4">
        <button
          onClick={handleSwitchToPassenger}
          className="w-full flex items-center justify-center gap-2 py-4 rounded-2xl bg-zinc-900 border border-zinc-800 text-white hover:bg-zinc-800 transition-colors"
        >
          <ArrowRightLeft className="size-5 text-yellow-400" />
          <span className="text-lg font-bold">切換去乘客版</span>
        </button>
      </div>

      {/* 重置 */}
      <div className="px-4 mt-4">
        <AlertDialog open={showResetConfirm} onOpenChange={setShowResetConfirm}>
          <AlertDialogTrigger asChild>
            <button className="w-full flex items-center justify-center gap-2 py-4 rounded-2xl bg-zinc-900 border border-zinc-800 text-zinc-400 hover:bg-zinc-800 transition-colors">
              <RotateCcw className="size-5" />
              <span className="text-base font-bold">重置示範數據</span>
            </button>
          </AlertDialogTrigger>
          <AlertDialogContent className="bg-zinc-900 border-zinc-700 text-white max-w-sm">
            <AlertDialogHeader>
              <AlertDialogTitle className="text-white text-xl font-bold">
                確定要重置？
              </AlertDialogTitle>
              <AlertDialogDescription className="text-zinc-400 text-base">
                所有行程、評分同設定會還原成預設狀態
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter className="gap-2 sm:gap-2">
              <AlertDialogCancel className="bg-zinc-800 text-white border-zinc-700 hover:bg-zinc-700 mt-2 sm:mt-0">
                取消
              </AlertDialogCancel>
              <AlertDialogAction
                onClick={handleReset}
                className="bg-red-500 hover:bg-red-600 text-white"
              >
                確定重置
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>

      {/* 登出 */}
      <div className="px-4 mt-4">
        <button
          onClick={handleLogout}
          className="w-full flex items-center justify-center gap-2 py-4 rounded-2xl bg-red-500/10 text-red-400 hover:bg-red-500/20 transition-colors border border-red-500/20"
        >
          <LogOut className="size-5" />
          <span className="text-lg font-bold">登出</span>
        </button>
      </div>

      {/* 底部導航 */}
      <div className="fixed bottom-0 left-0 right-0 bg-zinc-950 border-t border-zinc-800 z-50">
        <div className="grid grid-cols-3">
          <button
            onClick={() => navigate('/driver')}
            className="flex flex-col items-center justify-center py-3 text-zinc-400 hover:text-yellow-400 transition-colors"
          >
            <Car className="size-6 mb-0.5" />
            <span className="text-xs font-bold">已接</span>
          </button>
          <button
            onClick={() => navigate('/driver/earnings')}
            className="flex flex-col items-center justify-center py-3 text-zinc-400 hover:text-yellow-400 transition-colors"
          >
            <MapPin className="size-6 mb-0.5" />
            <span className="text-xs font-bold">已出</span>
          </button>
          <button
            onClick={() => navigate('/driver/profile')}
            className="flex flex-col items-center justify-center py-3 text-yellow-400"
          >
            <Settings className="size-6 mb-0.5" />
            <span className="text-xs font-bold">設定</span>
          </button>
        </div>
        <div className="h-2" />
      </div>
    </div>
  );
}
