import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, User, Phone, UserCircle, Lock, Eye, EyeOff, Check, Loader2, Globe, BadgeCheck, CreditCard, Car, UserPlus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { useI18n } from '@/lib/i18n';
import { useTheme } from '@/lib/theme-context';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/components/ui/sheet';
import { Image } from '@/components/ui/image';

const LOGO_URL = 'https://aka.doubaocdn.com/s/pKMrCCXYov';

export default function DriverRegisterPage() {
  const navigate = useNavigate();
  const { t, lang, setLang } = useI18n();
  const { primaryColor } = useTheme();
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [driverLicense, setDriverLicense] = useState('');
  const [idFront4, setIdFront4] = useState('');
  const [plate, setPlate] = useState('');
  const [referrerPhone, setReferrerPhone] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [langSheetOpen, setLangSheetOpen] = useState(false);
  const [agreed, setAgreed] = useState(false);

  const validatePhone = (p: string) => /^[569]\d{7}$/.test(p);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) {
      setError(t.driverRegister.nameRequired);
      return;
    }
    if (!validatePhone(phone)) {
      setError(t.driverRegister.phoneInvalid);
      return;
    }
    if (!username.trim()) {
      setError(t.driverRegister.accountRequired);
      return;
    }
    if (password.length < 6) {
      setError(t.driverRegister.passwordRequired);
      return;
    }
    if (password !== confirmPassword) {
      setError(t.driverRegister.passwordMismatch);
      return;
    }
    if (!driverLicense.trim()) {
      setError(t.driverRegister.licenseRequired);
      return;
    }
    if (!/^[A-Za-z0-9]{4}$/.test(idFront4)) {
      setError(t.driverRegister.idFront4Required);
      return;
    }
    if (!plate.trim()) {
      setError(t.driverRegister.plateRequired);
      return;
    }
    if (!agreed) {
      setError('請先閱讀並同意《收集個人資料聲明及私隱政策》');
      return;
    }
    setError('');
    setLoading(true);
    try {
      const { driverRegisterMock } = await import('@/lib/api');
      await driverRegisterMock({
        username: username.trim(),
        password,
        name: name.trim(),
        phone,
        driverLicense: driverLicense.trim().toUpperCase(),
        idFront4: idFront4.trim().toUpperCase(),
        plate: plate.trim().toUpperCase(),
        referrerPhone: referrerPhone.trim() || undefined,
      });
      setSubmitted(true);
      toast.success(t.driverRegister.registerSuccess);
    } catch (err: any) {
      if (String(err?.message || '').includes('exists')) {
        setError(t.driverRegister.accountExists);
      } else {
        setError(t.driverRegister.registerFailed);
      }
    } finally {
      setLoading(false);
    }
  };

  if (submitted) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-900 via-slate-800 to-slate-900 text-foreground flex flex-col relative overflow-hidden">
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div
            className="absolute top-16 left-8 size-72 rounded-full blur-3xl"
            style={{ backgroundColor: primaryColor, opacity: 0.15 }}
          />
        </div>
        <div className="relative z-10 pt-4 px-4 flex items-center gap-2">
          <Button variant="ghost" size="icon" className="text-white hover:text-white hover:bg-white/10" onClick={() => navigate('/')}>
            <ArrowLeft className="size-5" />
          </Button>
        </div>
        <div className="flex-1 flex items-center justify-center px-6">
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="text-center space-y-5 max-w-sm"
          >
            <div className="size-20 rounded-full bg-emerald-500/20 flex items-center justify-center mx-auto">
              <Check className="size-10 text-emerald-500" strokeWidth={3} />
            </div>
            <h1 className="text-2xl font-bold text-white">{t.driverRegister.registerSuccess}</h1>
            <p className="text-slate-300 text-sm leading-relaxed">{t.driverRegister.reviewNote}</p>
            <Button
              onClick={() => navigate('/driver/login')}
              className="rounded-full h-12 px-8"
            >
              {t.driverLogin.loginBtn}
            </Button>
          </motion.div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-900 via-slate-800 to-slate-900 text-foreground flex flex-col relative overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div
          className="absolute top-16 left-8 size-72 rounded-full blur-3xl"
          style={{ backgroundColor: primaryColor, opacity: 0.15 }}
        />
        <div className="absolute bottom-48 right-6 size-80 rounded-full bg-cyan-400/10 blur-3xl" />
      </div>

      <div className="relative z-10 pt-4 px-4 flex items-center gap-2">
        <Button variant="ghost" size="icon" className="text-white hover:text-white hover:bg-white/10" onClick={() => navigate('/driver/login')}>
          <ArrowLeft className="size-5" />
        </Button>
        <div className="flex-1" />
        <Sheet open={langSheetOpen} onOpenChange={setLangSheetOpen}>
          <SheetTrigger asChild>
            <Button variant="ghost" size="icon" className="text-white hover:text-white hover:bg-white/10">
              <Globe className="size-5" />
            </Button>
          </SheetTrigger>
          <SheetContent side="bottom" className="rounded-t-2xl">
            <SheetHeader>
              <SheetTitle>{t.language.current}</SheetTitle>
            </SheetHeader>
            <div className="mt-4 space-y-2">
              {(['zh-Hant', 'en', 'ja'] as const).map((l) => (
                <button
                  key={l}
                  onClick={() => { setLang(l); setLangSheetOpen(false); }}
                  className={`w-full px-4 py-3 rounded-xl text-left transition-colors ${
                    lang === l
                      ? 'bg-primary text-primary-foreground font-medium'
                      : 'bg-accent/50 hover:bg-accent'
                  }`}
                >
                  {t.language[l]}
                </button>
              ))}
            </div>
          </SheetContent>
        </Sheet>
      </div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
        className="flex-1 flex flex-col items-center justify-center px-6 py-6"
      >
        <div className="w-full max-w-sm space-y-5">
          <div className="text-center space-y-2">
            <Image src={LOGO_URL} alt="logo" className="size-14 mx-auto rounded-2xl shadow-lg" />
            <h1 className="text-2xl font-bold text-white">{t.driverRegister.title}</h1>
            <p className="text-sm text-slate-300">{t.driverRegister.subtitle}</p>
          </div>

          <Card className="shadow-2xl border-white/10 bg-white/95">
            <CardContent className="pt-6">
              <form onSubmit={handleSubmit} className="space-y-3.5">
                <div className="space-y-1.5">
                  <Label htmlFor="name">{t.driverRegister.nameLabel}</Label>
                  <div className="relative">
                    <User className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="name"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      placeholder={t.driverRegister.namePlaceholder}
                      className="pl-10 h-11"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="phone">{t.driverRegister.phoneLabel}</Label>
                  <div className="relative">
                    <Phone className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="phone"
                      type="tel"
                      inputMode="numeric"
                      maxLength={8}
                      value={phone}
                      onChange={(e) => setPhone(e.target.value.replace(/\D/g, ''))}
                      placeholder={t.driverRegister.phonePlaceholder}
                      className="pl-10 h-11"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="username">{t.driverRegister.accountLabel}</Label>
                  <div className="relative">
                    <UserCircle className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="username"
                      value={username}
                      onChange={(e) => setUsername(e.target.value)}
                      placeholder={t.driverRegister.accountPlaceholder}
                      className="pl-10 h-11"
                      autoComplete="username"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="driverLicense">{t.driverRegister.licenseLabel}</Label>
                  <div className="relative">
                    <BadgeCheck className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="driverLicense"
                      value={driverLicense}
                      onChange={(e) => setDriverLicense(e.target.value)}
                      placeholder={t.driverRegister.licensePlaceholder}
                      className="pl-10 h-11"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="idFront4">{t.driverRegister.idFront4Label}</Label>
                  <div className="relative">
                    <CreditCard className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="idFront4"
                      value={idFront4}
                      maxLength={4}
                      onChange={(e) => setIdFront4(e.target.value.replace(/[^A-Za-z0-9]/g, ''))}
                      placeholder={t.driverRegister.idFront4Placeholder}
                      className="pl-10 h-11 font-mono uppercase"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="plate">{t.driverRegister.plateLabel}</Label>
                  <div className="relative">
                    <Car className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="plate"
                      value={plate}
                      maxLength={8}
                      onChange={(e) => setPlate(e.target.value.replace(/[^A-Za-z0-9 ]/g, ''))}
                      placeholder={t.driverRegister.platePlaceholder}
                      className="pl-10 h-11 font-mono uppercase"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="referrerPhone">介紹人（可選）</Label>
                  <div className="relative">
                    <UserPlus className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="referrerPhone"
                      type="tel"
                      inputMode="numeric"
                      maxLength={8}
                      value={referrerPhone}
                      onChange={(e) => setReferrerPhone(e.target.value.replace(/\D/g, ''))}
                      placeholder="填已開通司機嘅電話號碼"
                      className="pl-10 h-11"
                    />
                  </div>
                  <p className="text-xs text-muted-foreground">介紹人＝會員號碼，要填已開通嘅司機電話</p>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="password">{t.driverRegister.passwordLabel}</Label>
                  <div className="relative">
                    <Lock className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="password"
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      placeholder={t.driverRegister.passwordPlaceholder}
                      className="pl-10 pr-10 h-11"
                      autoComplete="new-password"
                    />
                    <button
                      type="button"
                      onClick={() => setShowPassword((s) => !s)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
                    >
                      {showPassword ? <EyeOff className="size-4" /> : <Eye className="size-4" />}
                    </button>
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="confirmPassword">{t.driverRegister.confirmPasswordLabel}</Label>
                  <div className="relative">
                    <Lock className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                    <Input
                      id="confirmPassword"
                      type={showPassword ? 'text' : 'password'}
                      value={confirmPassword}
                      onChange={(e) => setConfirmPassword(e.target.value)}
                      placeholder={t.driverRegister.confirmPasswordPlaceholder}
                      className="pl-10 pr-10 h-11"
                      autoComplete="new-password"
                    />
                  </div>
                </div>

                {error && (
                  <div className="text-sm text-destructive text-center">{error}</div>
                )}

                {/* PCPD 收集個人資料聲明：申請會員前必須閱讀並同意 */}
                <div className="flex items-start gap-2.5 rounded-xl bg-muted/40 px-3 py-2.5">
                  <input
                    id="agreePrivacy"
                    type="checkbox"
                    checked={agreed}
                    onChange={(e) => setAgreed(e.target.checked)}
                    className="mt-0.5 size-4 shrink-0 rounded border-muted-foreground text-primary focus:ring-primary"
                  />
                  <label htmlFor="agreePrivacy" className="text-xs text-muted-foreground leading-relaxed">
                    我已經閱讀並同意
                    <button
                      type="button"
                      onClick={() => navigate('/privacy')}
                      className="text-primary underline ml-1"
                    >
                      收集個人資料聲明及私隱政策
                    </button>
                    <span className="text-destructive">*</span>
                  </label>
                </div>

                <Button
                  type="submit"
                  disabled={loading}
                  className="w-full h-12 rounded-full text-base font-semibold mt-2"
                >
                  {loading && <Loader2 className="size-4 mr-2 animate-spin" />}
                  {t.driverRegister.registerBtn}
                </Button>

                <div className="text-center pt-1">
                  <button
                    type="button"
                    onClick={() => navigate('/driver/login')}
                    className="text-sm text-primary hover:underline"
                  >
                    {t.driverRegister.loginLink}
                  </button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      </motion.div>
    </div>
  );
}
