import { useEffect, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { MapPin, Phone, Crown, X } from 'lucide-react';
import { useOrder } from '@/lib/order-context';
import { playWaterDrop as playWaterDropSound } from '@/lib/sound';
import { useI18n } from '@/lib/i18n';
import { toast } from 'sonner';

/**
 * 全局浮動接單卡（神飛的風格）：
 * 司機上線後，無論而家喺邊個頁面（我的／記錄／租車…），
 * 一有新單就會喺畫面頂部浮動彈出「接單 / 拒絕」，簡而精。
 * 喺司機大廳（/driver）同行車中（/driver/riding）唔重複顯示。
 */
export default function FloatingOrderOverlay() {
  const navigate = useNavigate();
  const location = useLocation();
  const { t } = useI18n();
  const {
    currentRole,
    isLoggedIn,
    driverVerified,
    driverOnline,
    hallOrders,
    refreshHallOrders,
    acceptOrder,
    rejectOrder,
  } = useOrder();

  const [activeOrder, setActiveOrder] = useState<any>(null);
  const [busy, setBusy] = useState(false);
  // 拒絕／收起過嘅單：讀 localStorage 持久記低，refresh 都唔會再彈返出嚟
  const [dismissedIds, setDismissedIds] = useState<Set<string>>(() => {
    try {
      const raw = localStorage.getItem('dikdou_rejected_orders');
      const list: string[] = raw ? JSON.parse(raw) : [];
      return new Set(list);
    } catch {
      return new Set();
    }
  });
  const seenIdsRef = useRef<Set<string>>(new Set());

  const persistDismissed = (id: string) => {
    try {
      const raw = localStorage.getItem('dikdou_rejected_orders');
      const list: string[] = raw ? JSON.parse(raw) : [];
      if (!list.includes(id)) {
        list.push(id);
        localStorage.setItem('dikdou_rejected_orders', JSON.stringify(list));
      }
    } catch { /* ignore */ }
  };

  // 條件：司機 + 已登入 + 已審批 + 上線 + 唔喺大廳/行車中頁 + 唔喺管理員後台
  const path = location.pathname;
  const eligible =
    currentRole === 'driver' &&
    isLoggedIn &&
    !!driverVerified &&
    !!driverOnline &&
    !path.startsWith('/admin') &&
    path !== '/driver' &&
    path !== '/driver/riding';

  // 喺其他頁面時自己每 5 秒 refresh 一次大廳單
  useEffect(() => {
    if (!eligible) return;
    refreshHallOrders();
    const timer = setInterval(refreshHallOrders, 5000);
    return () => clearInterval(timer);
  }, [eligible, refreshHallOrders]);

  // 有新單 → 揀最新嗰張彈出
  useEffect(() => {
    if (!eligible) return;
    const searching = hallOrders
      .filter((o) => o.status === 'searching')
      .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
    if (searching.length === 0) {
      setActiveOrder(null);
      return;
    }
    // 記低所有見過嘅單（判斷「新單」）
    for (const o of searching) seenIdsRef.current.add(o.id);
    // 淨係揀未拒絕過嘅單；全部拒絕過就收起，唔好 fallback 彈返已拒嘅單
    const candidate = searching.find((o) => !dismissedIds.has(o.id));
    if (!candidate) {
      setActiveOrder(null);
      return;
    }
    if (!activeOrder || activeOrder.id !== candidate.id) {
      setActiveOrder(candidate);
      // 有單提示音（1 下水滴，共用已解鎖 ctx，iPhone 都播到聲）
      playWaterDropSound();
      // 後台通知（Capacitor：App 縮埋都收到）
      try {
        import('@capacitor/local-notifications').then(({ LocalNotifications }) => {
          LocalNotifications.requestPermissions().then((perm) => {
            if (perm.display !== 'denied') {
              LocalNotifications.schedule({
                notifications: [{
                  id: Math.floor(Math.random() * 1e6),
                  title: '新單！',
                  body: `${candidate.pickup?.name || '上車點'} → ${candidate.destination?.name || '目的地'}　$${candidate.estimatedFare || '--'}`,
                  smallIcon: 'ic_launcher',
                  iconColor: '#16a34a',
                }],
              });
            }
          });
        }).catch(() => { /* ignore */ });
      } catch { /* ignore */ }
    }
  }, [eligible, hallOrders, activeOrder, dismissedIds]);

  if (!eligible || !activeOrder) return null;

  const handleAccept = async () => {
    if (busy) return;
    setBusy(true);
    // 10 秒 timeout：網絡慢都唔會永久卡喺「處理中…」
    const timer = setTimeout(() => { setBusy(false); }, 10000);
    try {
      await acceptOrder(activeOrder.id || activeOrder.driverId || 'demo', activeOrder.id);
      clearTimeout(timer);
      setActiveOrder(null);
      navigate('/driver/riding');
    } catch {
      clearTimeout(timer);
      toast.error('接單失敗，請再試');
      setBusy(false);
    }
  };

  const handleReject = async () => {
    if (busy) return;
    setBusy(true);
    const timer = setTimeout(() => { setBusy(false); }, 10000);
    try {
      await rejectOrder(activeOrder.id);
    } catch { /* ignore */ } finally {
      clearTimeout(timer);
    }
    persistDismissed(activeOrder.id);
    setDismissedIds((prev) => new Set(prev).add(activeOrder.id));
    setActiveOrder(null);
    setBusy(false);
  };

  const tip = activeOrder.tipAmount || activeOrder.tip || 0;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ y: -120, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: -120, opacity: 0 }}
        transition={{ type: 'spring', stiffness: 320, damping: 26 }}
        className="fixed top-2 left-2 right-2 z-[9999] pointer-events-none"
      >
        <div className="pointer-events-auto mx-auto max-w-md rounded-2xl bg-zinc-900 border border-zinc-700 shadow-2xl shadow-black/50 overflow-hidden">
          {/* 標題列 */}
          <div className="flex items-center justify-between px-4 py-2.5 bg-gradient-to-r from-green-600 to-emerald-700">
            <div className="flex items-center gap-2">
              {activeOrder.isVvipOrder || (activeOrder as any).vvipOnly ? (
                <Crown className="size-4 text-yellow-300" />
              ) : (
                <span className="size-2.5 rounded-full bg-red-500 animate-pulse" />
              )}
              <span className="text-white font-black text-base">新訂單</span>
              {activeOrder.carType === '6-seater' ? (
                <span className="px-2 py-0.5 rounded-full bg-white/20 text-white text-xs font-bold">6人車</span>
              ) : (
                <span className="px-2 py-0.5 rounded-full bg-white/20 text-white text-xs font-bold">4人車</span>
              )}
            </div>
            <button
              onClick={handleReject}
              className="size-7 rounded-full bg-white/15 hover:bg-white/25 flex items-center justify-center text-white"
              aria-label="暫時收起"
            >
              <X className="size-4" />
            </button>
          </div>

          {/* 路線 */}
          <div className="px-4 py-3">
            <div className="flex items-center gap-2">
              <div className="flex flex-col items-center gap-1">
                <span className="size-2.5 rounded-full bg-green-500" />
                <span className="w-0.5 h-6 bg-zinc-600" />
                <span className="size-2.5 rounded-full bg-red-500" />
              </div>
              <div className="flex-1 min-w-0 space-y-2">
                <div className="truncate text-white font-bold text-base">
                  {activeOrder.pickup?.name || '上車點'}
                </div>
                <div className="truncate text-zinc-400 text-base">
                  {activeOrder.destination?.name || '目的地'}
                </div>
              </div>
              <div className="text-right shrink-0">
                <div className="text-2xl font-black text-yellow-400 tabular-nums">
                  ${activeOrder.estimatedFare || '--'}
                </div>
                {tip > 0 && (
                  <div className="text-sm font-bold text-cyan-400 tabular-nums">+${tip} 貼士</div>
                )}
              </div>
            </div>
            {/* 接單前唔顯示乘客電話，接單之後先喺行程畫面見到 */}
          </div>

          {/* 接單 / 拒絕 */}
          <div className="px-4 pb-4 flex gap-3">
            <button
              onClick={handleReject}
              disabled={busy}
              className="flex-1 h-12 rounded-xl bg-zinc-700 hover:bg-zinc-600 text-white font-bold text-base disabled:opacity-60 transition-colors"
            >
              {busy ? '處理中…' : '拒絕'}
            </button>
            <button
              onClick={handleAccept}
              disabled={busy}
              className="flex-1 h-12 rounded-xl bg-green-600 hover:bg-green-500 text-white font-black text-base disabled:opacity-60 transition-colors"
            >
              {busy ? '處理中…' : '接單'}
            </button>
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}
