import { useEffect, useState } from 'react';

/**
 * APK 專用錯誤顯示層（淨係 APK 打包版啟用，VITE_HASH_ROUTER=true）
 * 目的：任何未捕捉錯誤都喺畫面顯示，唔會白屏／好似死機，方便用戶回報。
 */
export default function ApkErrorOverlay() {
  const [errors, setErrors] = useState<string[]>([]);

  useEffect(() => {
    const push = (msg: string) => {
      if (!msg) return;
      // 跨域腳本錯誤（瀏覽器通常只會俾「Script error」／帶有其他字符），冇實際訊息＝無意義，全部忽略唔顯示
      if (/script\s*error/i.test(msg)) return;
      const trimmed = msg.replace(/\s+/g, ' ').slice(0, 200);
      setErrors((prev) => [trimmed, ...prev].slice(0, 3));
    };
    const onError = (e: ErrorEvent) => {
      // 只顯示真正嘅 JS 程式錯誤；資源載入失敗（404 圖片／地圖 script）唔顯示，唔會嚇到用戶
      const realError = e.error || (e.message && !(e.target instanceof HTMLScriptElement) && !(e.target instanceof HTMLImageElement) && !(e.target instanceof HTMLLinkElement) ? e : null);
      if (realError) {
        const msg = (realError.error && realError.error.message) || realError.message;
        // React 併發渲染嘅 recovery error（如 #520「Minified React error」）——React 已經自動恢復、UI 正常，唔顯示誤報，避免嚇到用戶
        if (msg && !/^Minified React error/i.test(msg)) push(`JS錯誤: ${msg}`);
      }
    };
    const onRejection = (e: PromiseRejectionEvent) => {
      const reason = e.reason;
      push(`未處理: ${reason && reason.message ? reason.message : String(reason)}`);
    };
    window.addEventListener('error', onError);
    window.addEventListener('unhandledrejection', onRejection);
    return () => {
      window.removeEventListener('error', onError);
      window.removeEventListener('unhandledrejection', onRejection);
    };
  }, []);

  if (errors.length === 0) return null;

  return (
    <div className="fixed top-2 left-2 right-2 z-[9999] space-y-1">
      {errors.map((msg, i) => (
        <div
          key={i}
          className="rounded-lg border border-red-400 bg-red-50 px-3 py-2 text-xs text-red-700 shadow-lg"
        >
          {msg}
          <button
            className="ml-2 font-bold"
            onClick={() => setErrors((prev) => prev.filter((_, j) => j !== i))}
          >
            ✕
          </button>
        </div>
      ))}
    </div>
  );
}
