import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  ShieldCheck,
  Clock,
  XCircle,
  Upload,
  Check,
  FileCheck,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useI18n } from '@/lib/i18n';
import { useOrder } from '@/lib/order-context';

interface DocItem {
  key: string;
  label: string;
  icon: typeof ShieldCheck;
  status: 'submitted' | 'pending' | 'approved' | 'rejected';
  submittedAt?: string;
}

export default function DriverVerifyStatusPage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const { user } = useOrder();

  const status = user?.status || 'unverified';

  const docs: DocItem[] = [
    { key: 'idCard', label: t.driverVerifyStatus.idCard, icon: FileCheck, status: status === 'unverified' ? 'submitted' : 'approved' },
    { key: 'plate', label: t.driverVerifyStatus.plate, icon: ShieldCheck, status: status === 'approved' ? 'approved' : 'pending' },
    { key: 'taxiLicense', label: t.driverVerifyStatus.taxiLicense, icon: ShieldCheck, status: status === 'approved' ? 'approved' : status === 'rejected' ? 'rejected' : 'pending' },
    { key: 'insurance', label: t.driverVerifyStatus.insurance, icon: FileCheck, status: status === 'approved' ? 'approved' : 'pending' },
    { key: 'driverLicense', label: t.driverVerifyStatus.driverLicense, icon: FileCheck, status: status === 'approved' ? 'approved' : 'pending' },
  ];

  const statusBadge = (s: DocItem['status']) => {
    switch (s) {
      case 'approved':
        return (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-green-500/15 text-green-400 text-xs font-bold border border-green-500/30">
            <Check className="size-3" />
            {t.driverVerifyStatus.statusApproved}
          </span>
        );
      case 'pending':
        return (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-yellow-500/15 text-yellow-400 text-xs font-bold border border-yellow-500/30">
            <Clock className="size-3" />
            {t.driverVerifyStatus.statusPending}
          </span>
        );
      case 'rejected':
        return (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-red-500/15 text-red-400 text-xs font-bold border border-red-500/30">
            <XCircle className="size-3" />
            {t.driverVerifyStatus.statusRejected}
          </span>
        );
      default:
        return (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-zinc-700/50 text-zinc-400 text-xs font-bold border border-zinc-600">
            <Upload className="size-3" />
            {t.driverVerifyStatus.statusSubmitted}
          </span>
        );
    }
  };

  const overallBanner = () => {
    if (status === 'approved') {
      return (
        <div className="rounded-2xl bg-green-500/10 border border-green-500/30 p-5 flex items-center gap-4">
          <div className="size-14 rounded-xl bg-green-500/20 flex items-center justify-center shrink-0">
            <ShieldCheck className="size-7 text-green-400" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-lg font-bold text-white">{t.driverVerify.approved}</div>
            <div className="text-sm text-green-400/80 mt-0.5">
              {t.driverVerify.approvedDesc}
            </div>
          </div>
        </div>
      );
    }
    if (status === 'rejected') {
      return (
        <div className="rounded-2xl bg-red-500/10 border border-red-500/30 p-5 flex items-center gap-4">
          <div className="size-14 rounded-xl bg-red-500/20 flex items-center justify-center shrink-0">
            <XCircle className="size-7 text-red-400" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-lg font-bold text-white">{t.driverProfile.verifyRejected}</div>
            <div className="text-sm text-red-400/80 mt-0.5">
              {t.driverProfile.verifyRejectedDesc}
            </div>
          </div>
        </div>
      );
    }
    if (status === 'pending') {
      return (
        <div className="rounded-2xl bg-yellow-500/10 border border-yellow-500/30 p-5 flex items-center gap-4">
          <div className="size-14 rounded-xl bg-yellow-500/20 flex items-center justify-center shrink-0">
            <Clock className="size-7 text-yellow-400 animate-pulse" />
          </div>
          <div className="flex-1 min-w-0">
            <div className="text-lg font-bold text-white">{t.driverProfile.verifyPending}</div>
            <div className="text-sm text-yellow-400/80 mt-0.5">
              {t.driverProfile.verifyPendingDesc}
            </div>
            <div className="text-xs text-yellow-400/60 mt-1">
              {t.driverVerifyStatus.estimatedTime}
            </div>
          </div>
        </div>
      );
    }
    return (
      <div className="rounded-2xl bg-yellow-500/10 border border-yellow-500/30 p-5 flex items-center gap-4">
        <div className="size-14 rounded-xl bg-yellow-500/20 flex items-center justify-center shrink-0">
          <Upload className="size-7 text-yellow-400" />
        </div>
        <div className="flex-1 min-w-0">
          <div className="text-lg font-bold text-white">{t.driverProfile.unverifiedStatus}</div>
          <div className="text-sm text-yellow-400/80 mt-0.5">
            {t.driverProfile.unverifiedDesc}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* 頂部導航 */}
      <div className="sticky top-0 z-40 bg-black/80 backdrop-blur-md border-b border-zinc-800">
        <div className="flex items-center h-14 px-4">
          <button
            onClick={() => navigate(-1)}
            className="size-10 rounded-full flex items-center justify-center hover:bg-zinc-800 transition-colors -ml-2"
            aria-label={t.common.back}
          >
            <ArrowLeft className="size-5 text-white" />
          </button>
          <h1 className="flex-1 text-center text-lg font-black -ml-10">
            {t.driverVerifyStatus.title}
          </h1>
          <div className="w-10" />
        </div>
      </div>

      <div className="px-4 py-5 space-y-5 flex-1">
        {overallBanner()}

        {/* 文件狀態列表 */}
        <div>
          <h2 className="text-base font-bold text-white mb-3">
            {t.driverVerifyStatus.requiredDocs}
          </h2>
          <div className="rounded-2xl bg-zinc-900 border border-zinc-800 overflow-hidden">
            {docs.map((doc, i) => {
              const Icon = doc.icon;
              return (
                <div
                  key={doc.key}
                  className={`flex items-center gap-3 px-4 py-3.5 ${
                    i !== docs.length - 1 ? 'border-b border-zinc-800' : ''
                  }`}
                >
                  <div className="size-10 rounded-xl bg-yellow-500/15 flex items-center justify-center shrink-0">
                    <Icon className="size-5 text-yellow-400" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-bold text-white">{doc.label}</div>
                    {doc.submittedAt && (
                      <div className="text-xs text-zinc-500 mt-0.5">
                        {t.driverVerifyStatus.submittedAt}: {doc.submittedAt}
                      </div>
                    )}
                  </div>
                  {statusBadge(doc.status)}
                </div>
              );
            })}
          </div>
        </div>

        {/* 重新提交 */}
        <div className="rounded-2xl bg-zinc-900 border border-zinc-800 p-4">
          <p className="text-sm text-zinc-400 mb-3">
            {t.driverVerifyStatus.resubmitHint}
          </p>
          {status === 'unverified' ? (
            <Button
              onClick={() => navigate('/driver/verify')}
              className="w-full h-12 rounded-xl bg-yellow-500 hover:bg-yellow-400 text-black font-black"
            >
              {t.driverVerifyStatus.goToVerify}
            </Button>
          ) : (
            <Button
              onClick={() => navigate('/driver/verify')}
              variant="outline"
              className="w-full h-12 rounded-xl border-zinc-600 text-white hover:bg-zinc-800 font-bold"
            >
              {t.driverVerifyStatus.resubmitAll}
            </Button>
          )}
        </div>
      </div>
    </div>
  );
}
