// 共用音效模組
// 用單一 AudioContext + 首次用戶手勢解鎖，解決 iPhone Safari/WKWebView 自動播放限制
// （iOS 唔畀喺無用戶手勢下播聲，所以接貨有新單要 reuse 已解鎖嘅 ctx 先有聲）

let _ctx: AudioContext | null = null;

function getCtx(): AudioContext | null {
  if (_ctx) return _ctx;
  const C: any = window.AudioContext || (window as any).webkitAudioContext;
  if (!C) return null;
  try {
    _ctx = new C();
  } catch {
    return null;
  }
  return _ctx;
}

/** 解鎖 AudioContext（必須喺用戶手勢入面調用先有效） */
export function unlockAudio() {
  const c = getCtx();
  if (!c) return;
  if (c.state === 'suspended') {
    c.resume().catch(() => { /* ignore */ });
  }
}

/** 新單水滴提示聲（1 下）—— 用已解鎖嘅 singleton ctx */
export function playWaterDrop() {
  const c = getCtx();
  if (!c || c.state !== 'running') return;
  try {
    const now = c.currentTime;
    const osc = c.createOscillator();
    const gain = c.createGain();
    osc.type = 'sine';
    // 高頻滑落低頻＝水滴「叮」一聲
    osc.frequency.setValueAtTime(1900, now);
    osc.frequency.exponentialRampToValueAtTime(420, now + 0.16);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(0.45, now + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.28);
    osc.connect(gain);
    gain.connect(c.destination);
    osc.start(now);
    osc.stop(now + 0.32);
  } catch { /* ignore */ }
}

// 首次用戶手勢（撳/點/打字）就解鎖，之後任何時刻播聲都得
if (typeof document !== 'undefined') {
  const unlock = () => unlockAudio();
  ['pointerdown', 'touchstart', 'click', 'keydown'].forEach((ev) => {
    document.addEventListener(ev, unlock, { once: true, passive: true });
  });
}
