import { useState, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Wallet,
  TrendingUp,
  MapPin,
  Car,
  Settings,
  Clock,
  Star,
  ChevronRight,
  ArrowLeft,
  Banknote,
  CreditCard,
  DollarSign,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useI18n } from '@/lib/i18n';
import * as api from '@/lib/api';
import { useOrder } from '@/lib/order-context';
import BarChart, { type ChartDataPoint } from '@/components/BarChart';

interface IEarning {
  orderId: string;
  amount: number;
  tip: number;
  pickup: string;
  destination: string;
  createdAt: number;
  passengerRating?: number;
  passengerName?: string;
  paymentMethod?: string;
}

export default function DriverEarningsPage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const { isLoggedIn } = useOrder();
  const [allOrders, setAllOrders] = useState<IEarning[]>([]);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState<'today' | 'week' | 'month'>('today');

  // 登入守衛
  useEffect(() => {
    if (!isLoggedIn) {
      navigate('/driver/login', { replace: true });
    }
  }, [isLoggedIn, navigate]);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const orders = await api.getDriverEarnings();
        if (cancelled) return;
         const mapped: IEarning[] = orders.map((o: any) => ({
           orderId: o.id,
           amount: o.actualFare ?? o.estimatedFare,
           tip: o.tip ?? 0,
           pickup: o.pickup?.name || o.pickupName || '上車點',
           destination: o.destination?.name || o.destinationName || '目的地',
           createdAt: new Date(o.createdAt).getTime(),
           passengerRating: o.passengerRating ?? undefined,
           passengerName: o.passenger?.name || o.passengerName,
           paymentMethod: o.paymentMethod || 'cash',
         }));
        setAllOrders(mapped);
      } catch {
        // mock 兜底：本地造 3 條數據
         setAllOrders([
           {
             orderId: 'ORD001',
             amount: 78,
             tip: 5,
             pickup: '中環國際金融中心',
             destination: '銅鑼灣時代廣場',
             createdAt: Date.now() - 3600000 * 2,
             passengerRating: 5,
             passengerName: '陳先生',
             paymentMethod: 'octopus',
           },
           {
             orderId: 'ORD002',
             amount: 125,
             tip: 10,
             pickup: '旺角彌敦道',
             destination: '尖沙咀海港城',
             createdAt: Date.now() - 3600000 * 5,
             passengerRating: 4,
             passengerName: '李小姐',
             paymentMethod: 'cash',
           },
           {
             orderId: 'ORD003',
             amount: 320,
             tip: 20,
             pickup: '香港國際機場',
             destination: '中環交易廣場',
             createdAt: Date.now() - 86400000,
             passengerRating: 5,
             passengerName: '王先生',
             paymentMethod: 'credit',
           },
           {
             orderId: 'ORD004',
             amount: 55,
             tip: 0,
             pickup: '銅鑼灣崇光',
             destination: '灣仔港鐵站',
             createdAt: Date.now() - 86400000 * 2,
             passengerRating: 4,
             passengerName: '張女士',
             paymentMethod: 'fps',
           },
           {
             orderId: 'ORD005',
             amount: 180,
             tip: 15,
             pickup: '尖沙咀星光大道',
             destination: '東涌纜車站',
             createdAt: Date.now() - 86400000 * 3,
             passengerRating: 5,
             passengerName: '黃先生',
             paymentMethod: 'alipayhk',
           },
           {
             orderId: 'ORD006',
             amount: 95,
             tip: 0,
             pickup: '太子地鐵站',
             destination: '觀塘apm',
             createdAt: Date.now() - 86400000 * 4,
             passengerRating: 3,
             passengerName: '林小姐',
             paymentMethod: 'cash',
           },
           {
             orderId: 'ORD007',
             amount: 140,
             tip: 10,
             pickup: '中環蘭桂坊',
             destination: '大圍名城',
             createdAt: Date.now() - 86400000 * 5,
             passengerRating: 5,
             passengerName: '何先生',
             paymentMethod: 'wechat',
           },
           {
             orderId: 'ORD008',
             amount: 68,
             tip: 0,
             pickup: '旺角朗豪坊',
             destination: '深水埗電腦中心',
             createdAt: Date.now() - 86400000 * 6,
             passengerRating: 4,
             passengerName: '羅先生',
             paymentMethod: 'cash',
           },
         ]);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, []);

  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const todayStart = today.getTime();

  const weekStart = todayStart - 86400000 * 6; // 7 日內
  const monthStart = todayStart - 86400000 * 29; // 30 日內

  const periodOrders = useMemo(() => {
    if (period === 'today') return allOrders.filter((o) => o.createdAt >= todayStart);
    if (period === 'week') return allOrders.filter((o) => o.createdAt >= weekStart);
    return allOrders.filter((o) => o.createdAt >= monthStart);
  }, [allOrders, period, todayStart, weekStart, monthStart]);

  const todayOrders = allOrders.filter((o) => o.createdAt >= todayStart);
  const totalEarning = todayOrders.reduce((sum, e) => sum + e.amount, 0);

  // 時段統計
  const stats = useMemo(() => {
    const total = periodOrders.reduce((sum, e) => sum + e.amount, 0);
    const tipTotal = periodOrders.reduce((sum, e) => sum + e.tip, 0);
    const count = periodOrders.length;
    const avg = count > 0 ? Math.round(total / count) : 0;
    const cashEarnings = periodOrders
      .filter((e) => e.paymentMethod === 'cash')
      .reduce((sum, e) => sum + e.amount, 0);
    const digitalEarnings = periodOrders
      .filter((e) => e.paymentMethod !== 'cash')
      .reduce((sum, e) => sum + e.amount, 0);
    return { total, tipTotal, count, avg, cashEarnings, digitalEarnings };
  }, [periodOrders]);

  // 柱狀圖數據：日=今日每小時, 週=最近7日, 月=最近4週
  const chartData = useMemo<ChartDataPoint[]>(() => {
    if (period === 'today') {
      const hours = [9, 10, 11, 12, 13, 14, 15, 16];
      return hours.map((h) => {
        const hourStart = todayStart + h * 3600000;
        const hourEnd = hourStart + 3600000;
        const val = allOrders
          .filter((o) => o.createdAt >= hourStart && o.createdAt < hourEnd)
          .reduce((s, o) => s + o.amount, 0);
        return { label: `${h}時`, value: val };
      });
    }
    if (period === 'week') {
      const days = ['日', '一', '二', '三', '四', '五', '六'];
      const result: ChartDataPoint[] = [];
      for (let i = 6; i >= 0; i--) {
        const dayStart = todayStart - i * 86400000;
        const dayEnd = dayStart + 86400000;
        const d = new Date(dayStart);
        const val = allOrders
          .filter((o) => o.createdAt >= dayStart && o.createdAt < dayEnd)
          .reduce((s, o) => s + o.amount, 0);
        result.push({ label: `週${days[d.getDay()]}`, value: val });
      }
      return result;
    }
    // month - 4 weeks
    const result: ChartDataPoint[] = [];
    for (let i = 3; i >= 0; i--) {
      const weekEnd = todayStart - i * 7 * 86400000 + 86400000;
      const weekStartDate = weekEnd - 7 * 86400000;
      const val = allOrders
        .filter((o) => o.createdAt >= weekStartDate && o.createdAt < weekEnd)
        .reduce((s, o) => s + o.amount, 0);
      result.push({ label: `${4 - i}週前`, value: val });
    }
    return result;
  }, [period, allOrders, todayStart]);

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
  };

  const formatDate = (ts: number) => {
    const d = new Date(ts);
    if (ts >= todayStart) return '今日';
    return `${d.getMonth() + 1}/${d.getDate()}`;
  };

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      {/* 頂部導航 */}
      <div className="flex items-center justify-between px-4 pt-3 pb-3 border-b border-zinc-800">
        <button
          onClick={() => navigate(-1)}
          className="size-10 flex items-center justify-center rounded-full bg-zinc-900 hover:bg-zinc-800 transition-colors"
        >
          <ArrowLeft className="size-5 text-zinc-400" />
        </button>
        <h1 className="text-xl font-black">{t.driverEarnings.title}</h1>
        <div className="size-10" />
      </div>

      {/* 時段切換 Tab */}
      <div className="px-4 pt-3">
        <Tabs value={period} onValueChange={(v) => setPeriod(v as 'today' | 'week' | 'month')}>
          <TabsList className="w-full bg-zinc-900 p-1">
            <TabsTrigger value="today" className="flex-1 data-[state=active]:bg-zinc-800 data-[state=active]:text-yellow-400 text-zinc-400">
              {t.driverEarnings.today}
            </TabsTrigger>
            <TabsTrigger value="week" className="flex-1 data-[state=active]:bg-zinc-800 data-[state=active]:text-yellow-400 text-zinc-400">
              {t.driverEarnings.week}
            </TabsTrigger>
            <TabsTrigger value="month" className="flex-1 data-[state=active]:bg-zinc-800 data-[state=active]:text-yellow-400 text-zinc-400">
              {t.driverEarnings.month}
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </div>

      {/* 收入大字卡 */}
      <div className="px-4 py-4">
        <motion.div
          key={period}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          className="rounded-2xl bg-gradient-to-br from-yellow-600 to-yellow-700 p-5 shadow-xl shadow-yellow-900/30"
        >
          <div className="text-yellow-100 text-sm font-bold mb-1 flex items-center gap-2">
            <Wallet className="size-4" />
            {period === 'today' ? t.driverEarnings.todayEarnings : period === 'week' ? t.driverEarnings.weekEarnings : t.driverEarnings.monthEarnings}
          </div>
          <div className="text-4xl font-black text-white tabular-nums">
            ${stats.total.toFixed(0)}
            <span className="text-lg font-normal text-yellow-100 ml-1">.00</span>
          </div>
          <div className="mt-3 grid grid-cols-3 gap-2 text-yellow-100">
            <div className="flex items-center gap-1.5">
              <Car className="size-3.5" />
              <span className="text-sm">{stats.count} 單</span>
            </div>
            <div className="flex items-center gap-1.5">
              <TrendingUp className="size-3.5" />
              <span className="text-sm">平均 ${stats.avg}</span>
            </div>
            <div className="flex items-center gap-1.5">
              <DollarSign className="size-3.5" />
              <span className="text-sm">貼士 ${stats.tipTotal}</span>
            </div>
          </div>
        </motion.div>
      </div>

      {/* 現金/電子分項 */}
      <div className="px-4 mb-3">
        <div className="grid grid-cols-2 gap-3">
          <motion.div
            key={`cash-${period}`}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.05 }}
            className="rounded-xl bg-zinc-900 border border-zinc-800 p-4"
          >
            <div className="flex items-center gap-2 mb-1">
              <Banknote className="size-4 text-green-400" />
              <span className="text-sm text-zinc-400">{t.driverEarnings.cashEarnings}</span>
            </div>
            <div className="text-2xl font-black text-white tabular-nums">${stats.cashEarnings}</div>
          </motion.div>
          <motion.div
            key={`digital-${period}`}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 }}
            className="rounded-xl bg-zinc-900 border border-zinc-800 p-4"
          >
            <div className="flex items-center gap-2 mb-1">
              <CreditCard className="size-4 text-blue-400" />
              <span className="text-sm text-zinc-400">{t.driverEarnings.digitalEarnings}</span>
            </div>
            <div className="text-2xl font-black text-white tabular-nums">${stats.digitalEarnings}</div>
          </motion.div>
        </div>
      </div>

      {/* 收入走勢圖 */}
      <div className="px-4 mb-3">
        <motion.div
          key={`chart-${period}`}
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="rounded-xl bg-zinc-900 border border-zinc-800 p-4"
        >
          <div className="text-sm font-bold text-zinc-300 mb-3 flex items-center gap-2">
            <TrendingUp className="size-4 text-yellow-400" />
            {t.driverEarnings.chart}
          </div>
          <BarChart
            data={chartData}
            height={160}
            color="#eab308"
            yUnit="$"
          />
        </motion.div>
      </div>

      {/* 列表 */}
      <div className="flex-1 px-4 pb-28">
        <div className="text-sm font-bold text-zinc-400 px-2 py-2 flex items-center justify-between">
          <span>{t.driverEarnings.completed}</span>
          <span className="text-sm text-zinc-500">{periodOrders.length} 條</span>
        </div>

        {loading ? (
          <div className="text-center py-16 text-zinc-500">{t.driverEarnings.loading}</div>
        ) : periodOrders.length === 0 ? (
          <div className="text-center py-20">
            <div className="size-20 mx-auto mb-4 rounded-full bg-zinc-900 flex items-center justify-center">
              <Wallet className="size-10 text-zinc-700" />
            </div>
            <div className="text-lg font-bold text-zinc-500 mb-1">{t.driverEarnings.empty}</div>
            <div className="text-sm text-zinc-600">{t.driverEarnings.emptyDesc}</div>
          </div>
        ) : (
          <div className="space-y-2.5">
            {periodOrders.map((item, i) => (
              <motion.div
                key={item.orderId}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.04 }}
              >
                <div className="rounded-2xl bg-zinc-900 border border-zinc-800 p-4 active:bg-zinc-800/80 transition-colors">
                  <div className="flex items-start gap-3">
                    <div className="flex flex-col items-center pt-1.5">
                      <div className="size-2.5 rounded-full bg-green-400 shrink-0" />
                      <div className="w-px h-8 bg-zinc-700 my-1" />
                      <div className="size-2.5 rounded-full bg-red-500 shrink-0" />
                    </div>
                    <div className="flex-1 min-w-0 space-y-2">
                      <div className="text-lg font-bold text-white truncate">
                        {item.pickup}
                      </div>
                      <div className="text-lg font-bold text-white truncate">
                        {item.destination}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-2xl font-black text-yellow-400">
                        +${item.amount.toFixed(0)}
                      </div>
                      <div className="text-sm text-zinc-500 mt-1">
                        {formatDate(item.createdAt)} {formatTime(item.createdAt)}
                      </div>
                    </div>
                  </div>

                  <div className="mt-3 pt-3 border-t border-zinc-800 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <span className="text-sm text-zinc-400">
                        {item.passengerName || '乘客'}
                      </span>
                      {item.passengerRating !== undefined && (
                        <div className="flex items-center gap-0.5 text-yellow-400">
                          <Star className="size-3.5 fill-yellow-400" />
                          <span className="text-sm font-bold">{item.passengerRating}</span>
                        </div>
                      )}
                    </div>
                    <div className="flex items-center gap-2">
                      {item.tip > 0 && (
                        <span className="text-xs text-emerald-400 font-bold">+${item.tip} 貼士</span>
                      )}
                      <Badge className={`border-0 text-[10px] font-bold h-6 ${
                        item.paymentMethod === 'cash' ? 'bg-green-500/20 text-green-400' : 'bg-blue-500/20 text-blue-400'
                      }`}>
                        {item.paymentMethod === 'cash' ? '現金' : '電子'}
                      </Badge>
                    </div>
                  </div>
                </div>
              </motion.div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
