import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
  ArrowLeft,
  Car,
  User,
  Check,
  Upload,
  ShieldCheck,
  Loader2,
  Clock,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group';
import { useOrder } from '@/lib/order-context';
import { useI18n } from '@/lib/i18n';
import { toast } from 'sonner';

export default function DriverVerifyPage() {
  const navigate = useNavigate();
  const { submitDriverApplication } = useOrder();
  const { t } = useI18n();
  const [step, setStep] = useState<'form' | 'review' | 'pending'>('form');
  const [plate, setPlate] = useState('');
  const [licenseNo, setLicenseNo] = useState('');
  const [carType, setCarType] = useState<'4-seater' | '6-seater'>('4-seater');
  const [driverName, setDriverName] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const isFormValid =
    plate.trim().length >= 4 &&
    licenseNo.trim().length >= 4 &&
    driverName.trim().length >= 2;

  const handleSubmit = async () => {
    if (!isFormValid) return;
    setSubmitting(true);
    setStep('review');
    await new Promise((r) => setTimeout(r, 1000));
    submitDriverApplication({ driverName, licenseNo, plate, carType });
    setStep('pending');
    toast.success('申請已遞交');
  };

  const stepLabels = ['填寫資料', '提交審核', '等待結果'];

  return (
    <div className="min-h-screen bg-black text-white pb-8">
      {/* Header */}
      <div className="px-4 pt-6 pb-2">
        <div className="flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="size-11 rounded-full bg-zinc-800 flex items-center justify-center hover:bg-zinc-700 transition-colors"
          >
            <ArrowLeft className="size-5 text-white" />
          </button>
          <div>
            <h1 className="text-2xl font-black">司機認證</h1>
            <p className="text-base text-zinc-400">完成認證先可以接單</p>
          </div>
        </div>
      </div>

      {/* Steps indicator */}
      <div className="px-6 mt-6">
        <div className="flex items-center justify-between max-w-sm mx-auto">
          {[0, 1, 2].map((i) => {
            const stepIdx = step === 'form' ? 0 : step === 'review' ? 1 : 2;
            const passed = i < stepIdx;
            const active = i === stepIdx;
            return (
              <div key={i} className="flex items-center flex-1">
                <div className="flex flex-col items-center gap-1.5">
                  <div
                    className={`size-10 rounded-full flex items-center justify-center text-base font-black ${
                      passed
                        ? 'bg-yellow-500 text-black'
                        : active
                        ? 'bg-yellow-500 text-black'
                        : 'bg-zinc-800 text-zinc-500'
                    }`}
                  >
                    {passed ? <Check className="size-5" /> : i + 1}
                  </div>
                  <span className={`text-xs font-bold ${active || passed ? 'text-yellow-400' : 'text-zinc-500'}`}>
                    {stepLabels[i]}
                  </span>
                </div>
                {i < 2 && (
                  <div className={`flex-1 h-1 mx-2 rounded-full ${i < stepIdx ? 'bg-yellow-500' : 'bg-zinc-800'}`} />
                )}
              </div>
            );
          })}
        </div>
      </div>

      <AnimatePresence mode="wait">
        {step === 'form' && (
          <motion.div
            key="form"
            initial={{ opacity: 0, x: -20 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 20 }}
            className="px-4 mt-6 space-y-4"
          >
            {/* 司機資料 */}
            <div className="rounded-2xl bg-zinc-900 border border-zinc-800 p-5 space-y-4">
              <div className="flex items-center gap-2 mb-1">
                <User className="size-5 text-yellow-400" />
                <span className="text-lg font-bold text-white">司機資料</span>
              </div>
              <div className="space-y-2">
                <Label htmlFor="driverName" className="text-base text-zinc-300 font-bold">
                  司機姓名
                </Label>
                <Input
                  id="driverName"
                  value={driverName}
                  onChange={(e) => setDriverName(e.target.value)}
                  placeholder="輸入姓名"
                  className="h-12 bg-zinc-800 border-zinc-700 text-white text-lg placeholder:text-zinc-500 focus:border-yellow-500 focus:ring-yellow-500/30 rounded-xl"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="license" className="text-base text-zinc-300 font-bold">
                  駕駛執照編號
                </Label>
                <Input
                  id="license"
                  value={licenseNo}
                  onChange={(e) => setLicenseNo(e.target.value)}
                  placeholder="例如 TP12345"
                  className="h-12 bg-zinc-800 border-zinc-700 text-white text-lg placeholder:text-zinc-500 focus:border-yellow-500 focus:ring-yellow-500/30 rounded-xl font-mono"
                />
              </div>
            </div>

            {/* 車輛資料 */}
            <div className="rounded-2xl bg-zinc-900 border border-zinc-800 p-5 space-y-4">
              <div className="flex items-center gap-2">
                <Car className="size-5 text-yellow-400" />
                <span className="text-lg font-bold text-white">車輛資料</span>
              </div>
              <div className="space-y-2">
                <Label htmlFor="plate" className="text-base text-zinc-300 font-bold">
                  車牌號碼
                </Label>
                <Input
                  id="plate"
                  value={plate}
                  onChange={(e) => setPlate(e.target.value.toUpperCase())}
                  placeholder="例如 AB 1234"
                  className="h-12 bg-zinc-800 border-zinc-700 text-white text-lg placeholder:text-zinc-500 focus:border-yellow-500 focus:ring-yellow-500/30 rounded-xl font-mono tracking-wider"
                />
              </div>
              <div className="space-y-3">
                <Label className="text-base text-zinc-300 font-bold">車輛類型</Label>
                <RadioGroup
                  value={carType}
                  onValueChange={(v) => setCarType(v as '4-seater' | '6-seater')}
                  className="grid grid-cols-2 gap-3"
                >
                  <div>
                    <Label
                      htmlFor="car-4"
                      className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 cursor-pointer transition-all min-h-[6rem] text-center ${
                        carType === '4-seater'
                          ? 'border-yellow-500 bg-yellow-500/10 text-white'
                          : 'border-zinc-700 text-zinc-400 hover:border-zinc-600'
                      }`}
                    >
                      <RadioGroupItem value="4-seater" id="car-4" className="sr-only" />
                      <Car className="size-8 mb-1" />
                      <span className="text-base font-bold">4 人車</span>
                      <span className="text-xs opacity-70 mt-0.5">普通私家車</span>
                    </Label>
                  </div>
                  <div>
                    <Label
                      htmlFor="car-6"
                      className={`flex flex-col items-center justify-center p-4 rounded-xl border-2 cursor-pointer transition-all min-h-[6rem] text-center ${
                        carType === '6-seater'
                          ? 'border-yellow-500 bg-yellow-500/10 text-white'
                          : 'border-zinc-700 text-zinc-400 hover:border-zinc-600'
                      }`}
                    >
                      <RadioGroupItem value="6-seater" id="car-6" className="sr-only" />
                      <Car className="size-8 mb-1" />
                      <span className="text-base font-bold">6 人車</span>
                      <span className="text-xs opacity-70 mt-0.5">MPV / 七人車</span>
                    </Label>
                  </div>
                </RadioGroup>
              </div>
            </div>

            {/* 文件上傳 - mock */}
            <div className="rounded-2xl bg-zinc-900 border border-zinc-800 p-5 space-y-4">
              <div className="flex items-center gap-2">
                <Upload className="size-5 text-yellow-400" />
                <span className="text-lg font-bold text-white">文件上傳</span>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <button className="flex flex-col items-center justify-center p-4 rounded-xl border-2 border-dashed border-zinc-700 hover:border-yellow-500/50 hover:bg-yellow-500/5 transition-colors">
                  <Upload className="size-8 text-zinc-500 mb-1" />
                  <span className="text-sm text-zinc-400">身份證</span>
                  <span className="text-xs text-green-400 mt-1 font-bold">已上傳 ✓</span>
                </button>
                <button className="flex flex-col items-center justify-center p-4 rounded-xl border-2 border-dashed border-zinc-700 hover:border-yellow-500/50 hover:bg-yellow-500/5 transition-colors">
                  <Upload className="size-8 text-zinc-500 mb-1" />
                  <span className="text-sm text-zinc-400">駕駛執照</span>
                  <span className="text-xs text-green-400 mt-1 font-bold">已上傳 ✓</span>
                </button>
              </div>
              <p className="text-xs text-zinc-500 text-center">
                示範模式：文件已預設上傳
              </p>
            </div>

            {/* 提交 */}
            <Button
              size="lg"
              className="w-full h-14 rounded-2xl text-lg font-black bg-yellow-500 hover:bg-yellow-400 text-black shadow-lg shadow-yellow-500/30"
              onClick={handleSubmit}
              disabled={!isFormValid || submitting}
            >
              遞交認證申請
            </Button>

            <p className="text-xs text-zinc-500 text-center px-4">
              提交後大約 1-2 個工作天完成審核
            </p>
          </motion.div>
        )}

        {step === 'review' && (
          <motion.div
            key="review"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            exit={{ opacity: 0, scale: 0.95 }}
            className="px-4 mt-16 flex flex-col items-center text-center"
          >
            <div className="size-24 rounded-full bg-yellow-500/20 flex items-center justify-center mb-5 shadow-xl shadow-yellow-500/20">
              <Loader2 className="size-12 text-yellow-400 animate-spin" />
            </div>
            <h2 className="text-2xl font-black text-white mb-2">審核中...</h2>
            <p className="text-base text-zinc-400 max-w-xs">
              工作人員正在驗證你嘅資料，請稍等
            </p>
            <div className="mt-8 w-full max-w-xs space-y-3">
              <div className="flex items-center gap-4 p-4 rounded-xl bg-zinc-900 border border-zinc-800 text-left">
                <div className="size-8 rounded-full bg-green-500/20 flex items-center justify-center shrink-0">
                  <Check className="size-5 text-green-400" />
                </div>
                <span className="text-base font-bold text-white">身份證已驗證</span>
              </div>
              <div className="flex items-center gap-4 p-4 rounded-xl bg-zinc-900 border border-zinc-800 text-left">
                <div className="size-8 rounded-full bg-green-500/20 flex items-center justify-center shrink-0">
                  <Check className="size-5 text-green-400" />
                </div>
                <span className="text-base font-bold text-white">駕駛執照已驗證</span>
              </div>
              <div className="flex items-center gap-4 p-4 rounded-xl bg-yellow-500/10 border border-yellow-500/30 text-left">
                <Loader2 className="size-6 text-yellow-400 animate-spin ml-1 shrink-0" />
                <span className="text-base font-bold text-white">車牌資料驗證中</span>
              </div>
            </div>
          </motion.div>
        )}

        {step === 'pending' && (
          <motion.div
            key="pending"
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ type: 'spring', stiffness: 300, damping: 20 }}
            className="px-4 mt-8 flex flex-col items-center text-center"
          >
            <div className="size-28 rounded-full bg-yellow-500/20 flex items-center justify-center mb-5 shadow-xl shadow-yellow-500/20">
              <Clock className="size-14 text-yellow-400" />
            </div>
            <h2 className="text-3xl font-black text-white mb-2">申請已遞交</h2>
            <p className="text-base text-zinc-400 max-w-xs mb-6">
              工作人員會係 1-2 個工作天內審核
              <br />
              通過後會有通知
            </p>
            <div className="w-full max-w-sm p-5 rounded-2xl bg-zinc-900 border border-yellow-500/30 text-left space-y-4">
              <div className="flex items-center gap-4">
                <div className="size-12 rounded-xl bg-yellow-500/20 flex items-center justify-center shrink-0">
                  <User className="size-6 text-yellow-400" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-lg font-bold text-white truncate">
                    {driverName || '陳師傅'}
                  </div>
                  <div className="text-sm text-zinc-400 font-mono">
                    {licenseNo || 'TP12345'}
                  </div>
                </div>
                <span className="text-xs px-3 py-1.5 rounded-full bg-yellow-500/20 text-yellow-400 font-bold shrink-0">
                  審核中
                </span>
              </div>
              <div className="pt-3 border-t border-zinc-800 text-base text-zinc-400 flex items-center justify-between">
                <span>車牌：<span className="font-mono text-white font-bold">{plate || 'AB 1234'}</span></span>
                <span>車型：<span className="text-white font-bold">{carType === '6-seater' ? '6人車' : '4人車'}</span></span>
              </div>
            </div>
            <Button
              size="lg"
              className="w-full max-w-sm h-14 rounded-2xl mt-6 text-lg font-black bg-yellow-500 hover:bg-yellow-400 text-black"
              onClick={() => navigate('/driver')}
            >
              返去接單大廳
            </Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
