function readMyPostIds(): string[] {
  try {
    const raw = scopedStorage.getItem(MY_POSTS_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as string[];
      if (Array.isArray(parsed)) return parsed;
    }
  } catch {
    // ignore
  }
  return [];
}

function writeMyPostIds(ids: string[]) {
  try {
    scopedStorage.setItem(MY_POSTS_KEY, JSON.stringify(ids));
  } catch {
    // ignore
  }
}

// ============= 租車單存 server（俾所有人睇到） =============
const API_BASE = (import.meta.env.VITE_API_BASE as string | undefined) || (import.meta.env.DEV ? 'http://localhost:3001' : '');

// 裝置識別碼：用嚟判斷「呢張單係咪我自己發佈」+ 刪除權限
const DEVICE_KEY_STORAGE = 'hktaxi_device_key';
function getDeviceKey(): string {
  try {
    let k = scopedStorage.getItem(DEVICE_KEY_STORAGE);
    if (!k) {
      k = 'dev_' + Math.random().toString(36).slice(2, 10);
      scopedStorage.setItem(DEVICE_KEY_STORAGE, k);
    }
    return k;
  } catch {
    return 'dev_' + Math.random().toString(36).slice(2, 10);
  }
}

async function fetchRental(path: string, options?: RequestInit): Promise<any> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 12000);
  try {
    const res = await fetch(`${API_BASE}/api/rental${path}`, {
      headers: { 'Content-Type': 'application/json' },
      ...options,
      signal: controller.signal,
    });
    clearTimeout(timer);
    const text = await res.text();
    try { return text ? JSON.parse(text) : null; } catch { return { error: text }; }
  } finally {
    clearTimeout(timer);
  }
}

export async function loadRentalCars(): Promise<IRentalCar[]> {
  try {
    const data = await fetchRental('/');
    const myIds = readMyPostIds();
    if (data && Array.isArray(data.posts)) {
      return data.posts.map((p: any) => ({
        id: p.id,
        taxiColor: p.taxi_color || p.taxiColor || 'red',
        carModel: p.car_model || p.carModel || 'old_comf',
        shift: p.shift || 'full_day',
        district: p.district || 'kowloon',
        price: p.price || 0,
        priceUnit: p.price_unit || 'day',
        plate: p.plate || '',
        ownerName: p.owner_name || p.ownerName || '',
        ownerPhone: p.owner_phone || p.ownerPhone || '',
        year: p.year || 0,
        seats: p.seats || 4,
        note: p.note || '',
        rating: typeof p.rating === 'number' ? p.rating : 5.0,
        rentalCount: p.rental_count || 0,
        isMine: myIds.includes(p.id),
      }));
    }
    return [];
  } catch {
    // 連唔到 server：返回本地已有（雖然而家租車唔再本地存，返空）
    return [];
  }
}

export async function addRentalPost(car: Omit<IRentalCar, 'id' | 'isMine'>): Promise<IRentalCar> {
  const ownerKey = getDeviceKey();
  const data = await fetchRental('/', {
    method: 'POST',
    body: JSON.stringify({
      taxiColor: car.taxiColor, carModel: car.carModel, shift: car.shift,
      district: car.district, price: car.price, priceUnit: car.priceUnit,
      plate: car.plate, ownerName: car.ownerName, ownerPhone: car.ownerPhone,
      year: car.year, seats: car.seats, note: car.note, ownerKey,
    }),
  });
  if (!data || !data.ok || !data.id) {
    throw new Error(data?.error || '發佈失敗，請檢查網絡');
  }
  const newCar: IRentalCar = { ...car, id: data.id, isMine: true };
  const myIds = readMyPostIds();
  if (!myIds.includes(data.id)) {
    myIds.push(data.id);
    writeMyPostIds(myIds);
  }
  return newCar;
}

export async function removeRentalPost(carId: string): Promise<void> {
  const ownerKey = getDeviceKey();
  try {
    await fetchRental(`/${carId}?ownerKey=${encodeURIComponent(ownerKey)}`, { method: 'DELETE' });
  } catch {
    // ignore
  }
  const myIds = readMyPostIds().filter((id) => id !== carId);
  writeMyPostIds(myIds);
}

export function getMyRentalPostIds(): string[] {
  return readMyPostIds();
}

// ============= 收藏 =============
const FAVORITES_KEY = 'hktaxi_rental_favorites';

function readFavoriteIds(): string[] {
  try {
    const raw = scopedStorage.getItem(FAVORITES_KEY);
    if (raw) {
      const parsed = JSON.parse(raw) as string[];
      if (Array.isArray(parsed)) return parsed;
    }
  } catch {
    // ignore
  }
  return [];
}

function writeFavoriteIds(ids: string[]) {
  try {
    scopedStorage.setItem(FAVORITES_KEY, JSON.stringify(ids));
  } catch {
    // ignore
  }
}

export function getFavoriteIds(): string[] {
  return readFavoriteIds();
}

export function setFavoriteIds(ids: string[]): void {
  writeFavoriteIds(ids);
}

export function isFavorite(carId: string): boolean {
  return readFavoriteIds().includes(carId);
}

export function toggleFavorite(carId: string): boolean {
  const ids = readFavoriteIds();
  const idx = ids.indexOf(carId);
  if (idx >= 0) {
    ids.splice(idx, 1);
    writeFavoriteIds(ids);
    return false;
  } else {
    ids.push(carId);
    writeFavoriteIds(ids);
    return true;
  }
}
