import { createContext, useContext, useEffect, useState, useCallback, type ReactNode } from 'react';
import { scopedStorage, logger } from '@/lib/standalone-shim';

export type Lang = 'zh-Hant' | 'en' | 'ja';

// 字典類型
type Dict = typeof zhHant;

const LANG_KEY = 'hktaxi_language';

function readLang(): Lang {
  const raw = scopedStorage.getItem(LANG_KEY);
  if (raw === 'en') return 'en';
  if (raw === 'ja') return 'ja';
  return 'zh-Hant';
}

function writeLang(l: Lang) {
  scopedStorage.setItem(LANG_KEY, l);
}

