function getColorLabel(color: TaxiColor, t: ReturnType<typeof useI18n>['t']) {
  return t.rental.taxiColors[color];
}

function getColorHex(color: TaxiColor) {
  return RENTAL_TAXI_COLORS.find((c) => c.key === color)?.color ?? '#dc2626';
}

function getCarModelLabel(model: CarModelKey, t: ReturnType<typeof useI18n>['t']) {
  return t.rental.carModels[model];
}

function getShiftLabel(shift: ShiftType, t: ReturnType<typeof useI18n>['t']) {
  return t.rental.shifts[shift];
}

function getDistrictLabel(district: DistrictKey, t: ReturnType<typeof useI18n>['t']) {
  return t.rental.districts[district];
}

function getSeatsByModel(model: CarModelKey): number {
  if (model === 'mifa7' || model === 'vw_van') return 6;
  return 4;
}

function formatWhatsApp(phone: string): string {
  const digits = phone.replace(/\D/g, '');
  return `https://wa.me/852${digits}`;
}

