// ============= 出 Post 表單 =============
interface RentalPostFormProps {
  t: ReturnType<typeof useI18n>['t'];
  onSubmit: () => void;
  onCancel: () => void;
}

function RentalPostForm({ t, onSubmit, onCancel }: RentalPostFormProps) {
  const [district, setDistrict] = useState<DistrictKey | ''>('');
  const [taxiColor, setTaxiColor] = useState<TaxiColor | ''>('');
  const [carModel, setCarModel] = useState<CarModelKey | ''>('');
  const [shift, setShift] = useState<ShiftType | ''>('');
  const [price, setPrice] = useState('');
  const [plate, setPlate] = useState('');
  const [ownerName, setOwnerName] = useState('');
  const [phone, setPhone] = useState('');
  const [note, setNote] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  function validate(): boolean {
    const e: Record<string, string> = {};
    if (!district) e.district = t.rental.errors.districtRequired;
    if (!taxiColor) e.taxiColor = t.rental.errors.taxiColorRequired;
    if (!carModel) e.carModel = t.rental.errors.carModelRequired;
    if (!shift) e.shift = t.rental.errors.shiftRequired;
    if (!price.trim()) {
      e.price = t.rental.errors.priceRequired;
    } else if (isNaN(Number(price)) || Number(price) <= 0) {
      e.price = t.rental.errors.priceInvalid;
    }
    if (!phone.trim()) {
      e.phone = t.rental.errors.phoneRequired;
    } else if (!/^[0-9]{8}$/.test(phone.trim())) {
      e.phone = t.rental.errors.phoneInvalid;
    }
    setErrors(e);
    return Object.keys(e).length === 0;
  }

  function handleSubmit(ev: FormEvent) {
    ev.preventDefault();
    if (!validate()) return;

    setSubmitting(true);
    (async () => {
      try {
        await addRentalPost({
          district: district as DistrictKey,
          taxiColor: taxiColor as TaxiColor,
          carModel: carModel as CarModelKey,
          shift: shift as ShiftType,
          price: Number(price),
          priceUnit: 'day',
          plate: plate.trim() || '—',
          ownerName: ownerName.trim() || (t.rental.defaultOwner || '車主'),
          ownerPhone: phone.trim(),
          year: new Date().getFullYear(),
          seats: getSeatsByModel(carModel as CarModelKey),
          note: note.trim() || undefined,
          rating: 5.0,
          rentalCount: 0,
        });
        toast.success(t.rental.postSuccess);
        onSubmit();
      } catch (e: any) {
        toast.error(e?.message || t.common?.toast?.failed || '發佈失敗');
      } finally {
        setSubmitting(false);
      }
    })();
  }

  function appendTag(tagText: string) {
      const sep = t.rental.noteSeparator || '、';
      setNote((prev) => {
        if (!prev) return tagText;
        if (prev.includes(tagText)) return prev;
        return prev.endsWith(sep) || prev.endsWith(',') ? prev + tagText : prev + sep + tagText;
      });
  }

  function renderChipRow<T extends string>(
    items: { key: T; label?: string }[],
    value: T | '',
    setValue: (v: T) => void,
  ) {
    return (
      <div className="flex flex-wrap gap-2">
        {items.map((item) => {
          const label = item.label ?? item.key;
          const active = value === item.key;
          return (
            <button
              key={item.key}
              type="button"
              onClick={() => setValue(item.key)}
              className={`px-4 py-2.5 rounded-full text-base font-medium transition-all ${
                active
                  ? 'bg-primary text-primary-foreground shadow-md'
                  : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
              }`}
            >
              {label}
            </button>
          );
        })}
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-5">
      {/* 地區 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldDistrict}</label>
        {renderChipRow(
          RENTAL_DISTRICTS.map((d) => ({
            key: d.key,
            label: t.rental.districts[d.key as keyof typeof t.rental.districts] || d.labelZh,
          })),
          district,
          (v) => setDistrict(v as DistrictKey),
        )}
        {errors.district && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.district}</p>
        )}
      </div>

      {/* 的士顏色 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldTaxiColor}</label>
        <div className="flex flex-wrap gap-2">
          {RENTAL_TAXI_COLORS.map((c) => {
            const active = taxiColor === c.key;
            return (
              <button
                key={c.key}
                type="button"
                onClick={() => setTaxiColor(c.key)}
                className={`px-4 py-2.5 rounded-full text-base font-medium transition-all flex items-center gap-2 ${
                  active
                    ? 'bg-primary text-primary-foreground shadow-md'
                    : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
                }`}
              >
                <span
                  className="size-4 rounded-full border border-white/30"
                  style={{ backgroundColor: c.color }}
                />
                {t.rental.taxiColors[c.key]}
              </button>
            );
          })}
        </div>
        {errors.taxiColor && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.taxiColor}</p>
        )}
      </div>

      {/* 車型 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldCarModel}</label>
        {renderChipRow(
          RENTAL_CAR_MODELS.map((m) => ({
            key: m.key,
            label: t.rental.carModels[m.key],
          })),
          carModel,
          (v) => setCarModel(v as CarModelKey),
        )}
        {errors.carModel && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.carModel}</p>
        )}
      </div>

      {/* 更期 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldShift}</label>
        {renderChipRow(
          RENTAL_SHIFT_TYPES.map((s) => ({
            key: s.key,
            label: t.rental.shifts[s.key],
          })),
          shift,
          (v) => setShift(v as ShiftType),
        )}
        {errors.shift && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.shift}</p>
        )}
      </div>

      {/* 租金 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPrice}</label>
        <div className="relative">
          <span className="absolute left-4 top-1/2 -translate-y-1/2 text-foreground font-bold text-lg">
            {t.common.hkd}
          </span>
          <input
            type="number"
            inputMode="numeric"
            value={price}
            onChange={(e) => setPrice(e.target.value)}
            placeholder="650"
            className={`w-full h-14 pl-16 pr-4 rounded-xl border-2 text-lg font-bold tabular-nums bg-background text-foreground focus:outline-none focus:border-primary transition-colors ${
              errors.price ? 'border-destructive' : 'border-border'
            }`}
          />
        </div>
        {errors.price && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.price}</p>
        )}
      </div>

      {/* 車牌 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPlate}</label>
        <input
          type="text"
          value={plate}
          onChange={(e) => setPlate(e.target.value)}
          placeholder={t.rental.placeholderPlate}
          className="w-full h-14 px-4 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors"
        />
      </div>

      {/* 車主名 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldOwnerName}</label>
        <input
          type="text"
          value={ownerName}
          onChange={(e) => setOwnerName(e.target.value)}
          placeholder={t.rental.placeholderOwnerName}
          className="w-full h-14 px-4 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors"
        />
      </div>

      {/* 聯絡電話 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldPhone}</label>
        <input
          type="tel"
          inputMode="numeric"
          value={phone}
          onChange={(e) => setPhone(e.target.value)}
          placeholder={t.rental.placeholderPhone}
          maxLength={8}
          className={`w-full h-14 px-4 rounded-xl border-2 bg-background text-foreground text-lg font-medium tabular-nums focus:outline-none focus:border-primary transition-colors ${
            errors.phone ? 'border-destructive' : 'border-border'
          }`}
        />
        {errors.phone && (
          <p className="text-sm text-destructive font-medium">⚠️ {errors.phone}</p>
        )}
      </div>

      {/* 備註 + 快捷標籤 */}
      <div className="space-y-2">
        <label className="text-base font-bold text-foreground">{t.rental.fieldNote}</label>
        {/* 快捷標籤 */}
        <div className="space-y-2">
          <div className="flex items-center gap-1.5 text-sm text-muted-foreground font-medium">
            <Tag className="size-3.5" />
            {t.rental.quickTags}
          </div>
          <div className="flex flex-wrap gap-1.5">
            {QUICK_NOTE_TAGS.map((tag) => (
              <button
                key={tag.key}
                type="button"
                onClick={() => appendTag(t.rental.quickTag[tag.key as keyof typeof t.rental.quickTag])}
                className="px-3 py-1.5 rounded-full text-xs font-medium bg-primary/10 text-primary border border-primary/20 hover:bg-primary/20 transition-colors"
              >
                + {t.rental.quickTag[tag.key as keyof typeof t.rental.quickTag]}
              </button>
            ))}
          </div>
        </div>
        <textarea
          value={note}
          onChange={(e) => setNote(e.target.value)}
          placeholder={t.rental.placeholderNote}
          rows={3}
          className="w-full px-4 py-3 rounded-xl border-2 border-border bg-background text-foreground text-base focus:outline-none focus:border-primary transition-colors resize-none"
        />
      </div>

      {/* 按鈕 */}
      <div className="pt-2 flex gap-3">
        <button
          type="button"
          onClick={onCancel}
          className="h-14 px-6 rounded-xl bg-muted text-foreground font-bold text-base hover:bg-accent transition-colors"
        >
          {t.common.cancel}
        </button>
        <button
          type="submit"
          disabled={submitting}
          className="flex-1 h-14 rounded-xl bg-primary text-primary-foreground font-bold text-lg shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-transform disabled:opacity-60 disabled:hover:scale-100"
        >
          {submitting ? t.rental.submitting : t.rental.submitPost}
        </button>
      </div>
    </form>
  );
}

// ============= 主頁面 =============
export default function RentalPage() {
  const navigate = useNavigate();
  const { t } = useI18n();
  const { primaryColor } = useTheme();

  const [showPostForm, setShowPostForm] = useState(false);
  const [tab, setTab] = useState<'all' | 'mine' | 'favorites'>('all');
  const [cars, setCars] = useState<IRentalCar[]>([]);
  const [favIds, setFavIds] = useState<string[]>([]);
  const [removeDialogOpen, setRemoveDialogOpen] = useState(false);
  const [removeId, setRemoveId] = useState<string | null>(null);
  const [removeSubmitting, setRemoveSubmitting] = useState(false);

  const [district, setDistrict] = useState<DistrictKey | 'all'>('all');
  const [taxiColor, setTaxiColor] = useState<TaxiColor | 'all'>('all');
  const [carModel, setCarModel] = useState<CarModelKey | 'all'>('all');
  const [shift, setShift] = useState<ShiftType | 'all'>('all');
  const [priceRange, setPriceRange] = useState<PriceRangeKey>('all');

  // 初次加載
  useEffect(() => {
    let alive = true;
    (async () => {
      const cars = await loadRentalCars();
      if (alive) setCars(cars);
    })();
    setFavIds(getFavoriteIds());
    return () => { alive = false; };
  }, []);

  function refreshCars() {
    loadRentalCars().then(setCars).catch(() => {});
  }

  function handlePostSubmit() {
    setShowPostForm(false);
    refreshCars();
    setTab('mine');
  }

  function handleRemove(id: string) {
    setRemoveId(id);
    setRemoveDialogOpen(true);
  }

  async function confirmRemove() {
    if (!removeId) return;
    setRemoveSubmitting(true);
    try {
      await removeRentalPost(removeId);
      toast.success(t.rental.removed);
      refreshCars();
    } catch (e: any) {
      toast.error(e?.message || t.common?.toast?.failed || '刪除失敗');
    } finally {
      setRemoveSubmitting(false);
      setRemoveDialogOpen(false);
      setRemoveId(null);
    }
  }

  function handleToggleFav(id: string) {
    const nowFav = toggleFavorite(id);
    setFavIds(getFavoriteIds());
    toast.success(nowFav ? `♥ ${t.rental.favAdded || '已收藏'}` : `♡ ${t.rental.favRemoved || '已取消收藏'}`);
  }

  const filtered = useMemo(() => {
    let list = cars;
    if (tab === 'mine') {
      list = list.filter((c) => c.isMine);
    } else if (tab === 'favorites') {
      list = list.filter((c) => favIds.includes(c.id));
    }
    const range = RENTAL_PRICE_RANGES.find((r) => r.key === priceRange);
    return list.filter((car) => {
      if (district !== 'all' && car.district !== district) return false;
      if (taxiColor !== 'all' && car.taxiColor !== taxiColor) return false;
      if (carModel !== 'all' && car.carModel !== carModel) return false;
      if (shift !== 'all' && car.shift !== shift) return false;
      if (range && range.key !== 'all') {
        const price = car.price;
        // under_500: price < 500; 500_800: 500 <= price < 800; over_800: price >= 800
        if (range.key === 'under_500' && price >= 500) return false;
        if (range.key === '500_800' && (price < 500 || price >= 800)) return false;
        if (range.key === 'over_800' && price < 800) return false;
      }
      return true;
    });
  }, [cars, tab, district, taxiColor, carModel, shift, priceRange, favIds]);

  type FilterKey = 'district' | 'taxiColor' | 'carModel' | 'shift' | 'priceRange';
  type FilterValue = string | 'all';

  function renderFilterRow(
    key: FilterKey,
    value: FilterValue,
    setValue: (v: FilterValue) => void,
    label: string,
    allLabel: string,
    items: { key: string; label?: string }[],
  ) {
    const getItemLabel = (item: { key: string; label?: string }) => {
      if (item.label) return item.label;
      switch (key) {
        case 'district':
          return t.rental.districts[item.key as DistrictKey];
        case 'taxiColor':
          return t.rental.taxiColors[item.key as TaxiColor];
        case 'carModel':
          return t.rental.carModels[item.key as CarModelKey];
        case 'shift':
          return t.rental.shifts[item.key as ShiftType];
        case 'priceRange':
          return t.rental.priceRange[item.key as keyof typeof t.rental.priceRange];
      }
    };

    return (
      <div className="space-y-2">
        <div className="text-sm font-semibold text-foreground">{label}</div>
        <div className="flex flex-wrap gap-2">
          <button
            onClick={() => setValue('all')}
            className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all ${
              value === 'all'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
            }`}
          >
            {allLabel}
          </button>
          {items.map((item) => (
            <button
              key={item.key}
              onClick={() => setValue(item.key)}
              className={`px-3.5 py-2 rounded-full text-sm font-medium transition-all ${
                value === item.key
                  ? 'bg-primary text-primary-foreground shadow-md'
                  : 'bg-muted text-muted-foreground hover:bg-accent hover:text-foreground'
              }`}
            >
              {getItemLabel(item)}
            </button>
          ))}
        </div>
      </div>
    );
  }

  // 出 Post 表單頁
  if (showPostForm) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
        {/* 背景裝飾 */}
        <div className="fixed inset-0 overflow-hidden pointer-events-none">
          <div
            className="absolute top-0 left-0 size-72 rounded-full blur-3xl opacity-10"
            style={{ backgroundColor: primaryColor }}
          />
        </div>

        {/* 頂部導航 */}
        <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
          <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
            <button
              onClick={() => setShowPostForm(false)}
              className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0"
              aria-label={t.common.cancel}
            >
              <X className="size-5 text-foreground" />
            </button>
            <h1 className="text-lg font-bold flex-1 text-center pr-10">{t.rental.postTitle}</h1>
          </div>
        </div>

        {/* 表單內容 */}
        <div className="relative z-10 max-w-lg mx-auto px-4 pt-5 pb-10">
          <p className="text-muted-foreground text-base mb-5">{t.rental.postSubtitle}</p>
          <RentalPostForm
            t={t}
            onSubmit={handlePostSubmit}
            onCancel={() => setShowPostForm(false)}
          />
        </div>
      </div>
    );
  }

  // 列表頁
  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground">
      {/* 背景裝飾 */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none">
        <div
          className="absolute top-0 left-0 size-72 rounded-full blur-3xl opacity-10"
          style={{ backgroundColor: primaryColor }}
        />
        <div className="absolute bottom-1/3 right-0 size-80 rounded-full bg-amber-200/20 blur-3xl" />
      </div>

      {/* 頂部導航 */}
      <div className="relative z-10 sticky top-0 bg-background/80 backdrop-blur-md border-b border-border/40">
        <div className="max-w-lg mx-auto px-4 h-14 flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="size-10 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0"
            aria-label={t.rental.back}
          >
            <ArrowLeft className="size-5 text-foreground" />
          </button>
          <h1 className="text-lg font-bold flex-1 text-center">{t.rental.title}</h1>
          <button
            onClick={() => setShowPostForm(true)}
            className="size-10 rounded-full bg-primary text-primary-foreground flex items-center justify-center shadow-md hover:scale-110 active:scale-95 transition-transform shrink-0"
            aria-label={t.rental.postBtn}
          >
            <Plus className="size-5" />
          </button>
        </div>

        {/* Tab 切換 */}
        <div className="max-w-lg mx-auto px-4 pb-3 flex gap-2">
          <button
            onClick={() => setTab('all')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'all'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <Grid3X3 className="size-4" />
            {t.rental.allCarsTab}
          </button>
          <button
            onClick={() => setTab('favorites')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'favorites'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <Heart className="size-4" />
            {t.rental.favoritesTab}
          </button>
          <button
            onClick={() => setTab('mine')}
            className={`flex-1 h-10 rounded-full text-sm font-bold transition-all flex items-center justify-center gap-1.5 ${
              tab === 'mine'
                ? 'bg-primary text-primary-foreground shadow-md'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
            <List className="size-4" />
            {t.rental.myPostsTab}
          </button>
        </div>
      </div>

      {/* 內容 */}
      <div className="relative z-10 max-w-lg mx-auto px-4 pt-4 pb-8">
        {/* 副標題 / 出租按鈕 */}
        <div className="flex items-center gap-3 mb-5">
          <p className="text-muted-foreground text-base flex-1">{t.rental.subtitle}</p>
          <button
            onClick={() => setShowPostForm(true)}
            className="h-10 px-4 rounded-full bg-primary text-primary-foreground font-bold text-sm shadow-md hover:scale-105 active:scale-95 transition-transform flex items-center gap-1.5 shrink-0"
          >
            <Plus className="size-4" />
            {t.rental.postBtn}
          </button>
        </div>

        {/* 篩選區 */}
        <div className="bg-card/80 backdrop-blur rounded-2xl border border-border p-4 mb-5 space-y-4 shadow-sm">
          <p className="text-xs text-muted-foreground font-medium">{t.rental.filterHint}</p>

          {renderFilterRow(
            'district',
            district,
            (v) => setDistrict(v as DistrictKey | 'all'),
            t.rental.district,
            t.rental.allDistricts,
            RENTAL_DISTRICTS.map((d) => ({ key: d.key })),
          )}

          {renderFilterRow(
            'taxiColor',
            taxiColor,
            (v) => setTaxiColor(v as TaxiColor | 'all'),
            t.rental.taxiColor,
            t.rental.allColors,
            RENTAL_TAXI_COLORS.map((c) => ({ key: c.key })),
          )}

          {renderFilterRow(
            'carModel',
            carModel,
            (v) => setCarModel(v as CarModelKey | 'all'),
            t.rental.carModel,
            t.rental.allModels,
            RENTAL_CAR_MODELS.map((m) => ({ key: m.key })),
          )}

          {renderFilterRow(
            'shift',
            shift,
            (v) => setShift(v as ShiftType | 'all'),
            t.rental.shift,
            t.rental.allShifts,
            RENTAL_SHIFT_TYPES.map((s) => ({ key: s.key })),
          )}

          {renderFilterRow(
            'priceRange',
            priceRange,
            (v) => setPriceRange(v as PriceRangeKey),
            t.rental.priceFilter,
            t.rental.priceRange.all,
            RENTAL_PRICE_RANGES.filter((r) => r.key !== 'all').map((r) => ({ key: r.key })),
          )}
        </div>

        {/* 結果數量 */}
        <div className="text-sm text-muted-foreground mb-3 font-medium">
          {t.rental.resultCount.replace('{count}', String(filtered.length))}
        </div>

        {/* 車輛列表 */}
        {filtered.length === 0 ? (
          <div className="bg-card rounded-2xl border border-border p-10 text-center">
            <CarIcon className="size-12 mx-auto text-muted-foreground/40 mb-3" />
            <p className="text-muted-foreground mb-4">
              {tab === 'mine'
                ? t.rental.noMyPosts
                : tab === 'favorites'
                ? t.rental.noFavorites
                : t.rental.empty}
            </p>
            {(tab === 'mine' || tab === 'favorites') && (
              <button
                onClick={() => (tab === 'mine' ? setShowPostForm(true) : setTab('all'))}
                className="h-12 px-6 rounded-full bg-primary text-primary-foreground font-bold text-sm shadow-md hover:scale-105 active:scale-95 transition-transform inline-flex items-center gap-1.5"
              >
                <Plus className="size-4" />
                {tab === 'mine' ? t.rental.goPost : t.rental.allCarsTab}
              </button>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            {filtered.map((car) => (
              <RentalCarCard
                key={car.id}
                car={car}
                t={t}
                isFav={favIds.includes(car.id)}
                onToggleFav={handleToggleFav}
                onRemove={car.isMine ? handleRemove : undefined}
              />
            ))}
          </div>
        )}
      </div>

      {/* 下架確認對話框 */}
      <AlertDialog open={removeDialogOpen} onOpenChange={(o) => { if (!o && !removeSubmitting) setRemoveDialogOpen(false); }}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{t.rental.removeTitle || '確認下架？'}</AlertDialogTitle>
            <AlertDialogDescription>
              {t.rental.removeConfirm}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={removeSubmitting}>{t.common.cancel}</AlertDialogCancel>
            <AlertDialogAction
              onClick={(e) => { e.preventDefault(); confirmRemove(); }}
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              disabled={removeSubmitting}
            >
              {removeSubmitting ? t.rental.submitting : t.common.confirm}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
