import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Download, Smartphone, X } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { scopedStorage } from '@/lib/standalone-shim';
import { useI18n } from '@/lib/i18n';
import { Image } from '@/components/ui/image';

interface PwaInstallPromptProps {
  /**
   * 'auto' = 舊模式：等 beforeinstallprompt 事件先觸發，7 日內唔重複彈（用於其他頁面）
   * 'welcome' = 歡迎頁模式：一打開就顯示，每次入歡迎頁都彈（除已安裝或已關閉）
   */
  mode?: 'auto' | 'welcome';
}

const DISMISS_KEY = 'pwa_install_dismissed';
const DISMISS_DURATION = 7 * 24 * 60 * 60 * 1000; // 7 日（auto 模式用）

export default function PwaInstallPrompt({ mode = 'auto' }: PwaInstallPromptProps) {
  const [show, setShow] = useState(false);
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [isInstalled, setIsInstalled] = useState(false);
  const [isIos, setIsIos] = useState(false);
  const { t } = useI18n();

  // APK 打包版（VITE_HASH_ROUTER=true）：本身已經係 App，唔彈安裝提示
  if (import.meta.env.VITE_HASH_ROUTER === 'true') {
    return null;
  }

  useEffect(() => {
    // 檢查是否已安裝
    if (window.matchMedia('(display-mode: standalone)').matches || (window.navigator as any).standalone) {
      setIsInstalled(true);
      return;
    }

    // 檢查 iOS
    const ua = navigator.userAgent.toLowerCase();
    const ios = /iphone|ipad|ipod/.test(ua) && !(window as any).MSStream;
    setIsIos(ios);

    // welcome 模式：每次入頁都顯示（唔受 7 日限制）
    if (mode === 'welcome') {
      const timer = setTimeout(() => {
        setShow(true);
      }, 300);

      const handler = (e: Event) => {
        e.preventDefault();
        setDeferredPrompt(e);
      };
      window.addEventListener('beforeinstallprompt', handler);

      return () => {
        clearTimeout(timer);
        window.removeEventListener('beforeinstallprompt', handler);
      };
    }

    // auto 模式（舊邏輯）：等瀏覽器觸發 + 7 日限制
    try {
      const dismissedAt = scopedStorage.getItem(DISMISS_KEY);
      if (dismissedAt && Date.now() - Number(dismissedAt) < DISMISS_DURATION) {
        return;
      }
    } catch {
      // ignore
    }

    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
      setShow(true);
    };

    window.addEventListener('beforeinstallprompt', handler);

    if (ios) {
      const timer = setTimeout(() => {
        setShow(true);
      }, 2000);
      return () => clearTimeout(timer);
    }

    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
    };
  }, [mode]);

  const handleInstall = async () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      const { outcome } = await deferredPrompt.userChoice;
      if (outcome === 'accepted') {
        setShow(false);
      }
      setDeferredPrompt(null);
    } else if (isIos) {
      // iOS：主按鈕亦顯示 iOS 簡短指引
      // （維持不變，按鈕下方已有 iOS 文字指引）
    } else {
      // Android 不支援原生安裝：顯示瀏覽器選單指引
      // （維持舊邏輯，按鈕點擊無展開，維持簡潔）
    }
  };

  const handleDismiss = () => {
    setShow(false);
    if (mode === 'auto') {
      try {
        scopedStorage.setItem(DISMISS_KEY, String(Date.now()));
      } catch {
        // ignore
      }
    }
  };

  if (!show || isInstalled) return null;

  return (
    <AnimatePresence>
      <motion.div
        initial={{ y: 100, opacity: 0 }}
        animate={{ y: 0, opacity: 1 }}
        exit={{ y: 100, opacity: 0 }}
        transition={{ type: 'spring', damping: 25, stiffness: 300 }}
        className="fixed bottom-20 left-3 right-3 z-50 max-w-md mx-auto"
      >
        <div className="bg-white rounded-2xl shadow-2xl shadow-black/20 border border-slate-200 overflow-hidden">
          <div className="p-4">
            <div className="flex items-start gap-3">
              {/* App Icon */}
              <div className="size-14 rounded-xl bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center shrink-0 shadow-lg shadow-emerald-500/30 overflow-hidden">
                <Image
                  src="https://aka.doubaocdn.com/s/pKMrCCXYov"
                  alt="的道"
                  className="w-full h-full object-cover"
                />
              </div>

              {/* 內容 */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <h4 className="font-bold text-foreground text-base">{t.pwa.title}</h4>
                  <span className="text-[10px] bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded-full font-bold">
                    {t.pwa.new}
                  </span>
                </div>
                <p className="text-xs text-muted-foreground mt-0.5 leading-relaxed">
                  {t.pwa.subtitle}<br />
                  <span className="text-emerald-600 font-medium">{t.pwa.features}</span>
                </p>

                {/* 主 CTA 按鈕 + 關閉 */}
                <div className="flex items-center gap-2 mt-3">
                  <Button
                    size="sm"
                    className="h-11 rounded-full text-sm font-bold flex-1 bg-primary hover:bg-primary/90"
                    onClick={handleInstall}
                  >
                    <Download className="size-4 mr-1.5" />
                    {t.pwa.addToHome}
                  </Button>
                  <button
                    onClick={handleDismiss}
                    className="size-11 rounded-full bg-slate-100 flex items-center justify-center hover:bg-slate-200 transition-colors shrink-0"
                    aria-label="關閉"
                  >
                    <X className="size-4 text-slate-500" />
                  </button>
                </div>

                {/* iOS 簡短指引（一行文字） */}
                {isIos && (
                  <div className="mt-3 pt-3 border-t border-slate-100">
                    <p className="text-[11px] text-muted-foreground leading-relaxed">
                      {t.pwa.iosGuide}
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* 底部特色 */}
          <div className="bg-slate-50 px-4 py-2 flex items-center justify-around border-t border-slate-100">
            <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
              <Smartphone className="size-3.5 text-emerald-500" />
              <span>{t.pwa.desktop}</span>
            </div>
            <div className="w-px h-3 bg-slate-200" />
            <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
              <Download className="size-3.5 text-emerald-500" />
              <span>{t.pwa.offline}</span>
            </div>
            <div className="w-px h-3 bg-slate-200" />
            <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground">
              <span className="size-3.5 rounded-full bg-emerald-500 text-white flex items-center justify-center text-[9px] font-bold">免</span>
              <span>{t.pwa.free}</span>
            </div>
          </div>
        </div>
      </motion.div>
    </AnimatePresence>
  );
}
