// ========== 乘客電話登入 ==========
const DEMO_PASSENGER_CODE = '123456';

export async function passengerPhoneLogin(phone: string, code: string) {
  try {
    const res = await api.post(`/auth/passenger/phone-login`, { phone, code });
    // 防護：WebView 有機會將請求當成網頁回傳 HTML，要驗證結構先當成功
    if (res.data && res.data.user && res.data.token) {
      return res.data;
    }
    // 回應唔可用 → 跌落下面 catch 行本地 mock 兜底（唔可以靜靜地回 undefined）
    throw new Error('Invalid response');
  } catch {
    // 本地 mock 兜底
    if (code !== DEMO_PASSENGER_CODE) {
      throw new Error('Invalid code');
    }
    if (!/^[569]\d{7}$/.test(phone)) {
      throw new Error('Invalid phone');
    }
    const user = {
      id: `p_${phone}`,
      username: phone,
      phone,
      name: '乘客',
      avatar: null,
      rating: 4.8,
      rating_count: 5,
    };
    return {
      user,
      token: `passenger-${phone}-token`,
    };
  }
}

