export async function getAdminDrivers(status: string = 'pending', page: number = 1, pageSize: number = 20) {
  try {
    const res = await api.get(`/admin/drivers?status=${status}&page=${page}&pageSize=${pageSize}`);
    const data = res.data;
    return {
      drivers: Array.isArray(data) ? data : (data?.drivers ?? []),
      total: data?.total ?? (Array.isArray(data) ? data.length : 0),
      page: data?.page ?? page,
      pageSize: data?.pageSize ?? pageSize,
    };
  } catch {
    // 本地 mock：從 DRIVER_REGISTER_KEY 組裝（示範帳號已刪除）
    const raw = scopedStorage.getItem(DRIVER_REGISTER_KEY);
    const registered = raw ? JSON.parse(raw) : {};
    const drivers: any[] = [];

    // 註冊帳號
    Object.entries(registered).forEach(([username, reg]: [string, any]) => {
      if (status === 'all' || reg.status === status) {
        drivers.push({
          id: `d_${username}`,
          username,
          name: reg.name,
          phone: reg.phone,
          plate: '',
          carModel: '',
          driverLicense: '',
          status: reg.status || 'pending',
          rating: 0,
          ratingCount: 0,
          is_vvip: false,
          vvip_applied: false,
          vvip_requested_at: null,
          createdAt: reg.createdAt || Date.now(),
        });
      }
    });

    const sorted = drivers.sort((a, b) => b.createdAt - a.createdAt);
    return { drivers: sorted, total: sorted.length, page, pageSize };
  }
}

