export async function approveDriver(id: string, options?: { grantVip?: boolean; grantVvipTrial?: boolean }) {
  try {
    const res = await api.post(`/admin/drivers/${id}/approve`, options || {});
    return res.data;
  } catch {
    // 本地 mock：更新 DRIVER_REGISTER_KEY 中嘅狀態
    const raw = scopedStorage.getItem(DRIVER_REGISTER_KEY);
    const registered = raw ? JSON.parse(raw) : {};
    const username = id.replace(/^d_/, '');
    if (registered[username]) {
      registered[username].status = 'approved';
      registered[username].reviewedAt = Date.now();
      scopedStorage.setItem(DRIVER_REGISTER_KEY, JSON.stringify(registered));
    }
    // 同步 driverApplications storage (order-context 用)
    try {
      const appsRaw = scopedStorage.getItem('hktaxi_driverApplications');
      if (appsRaw) {
        const apps = JSON.parse(appsRaw);
        const idx = apps.findIndex((a: any) => a.id === id);
        if (idx !== -1) {
          apps[idx].status = 'approved';
          apps[idx].reviewedAt = Date.now();
          scopedStorage.setItem('hktaxi_driverApplications', JSON.stringify(apps));
        }
      }
    } catch { /* ignore */ }
    window.dispatchEvent(new CustomEvent('hktaxi-driver-approved', { detail: { driverId: id } }));
    return { success: true };
  }
}

