export function createAdminStream(token?: string): EventSource {
  const t = token || localStorage.getItem('hktaxi_adminToken') || '';
  return new EventSource(`${API_BASE}/api/admin/stream?token=${encodeURIComponent(t)}`, { withCredentials: true });
}

export default api;
