// EXPORTS: calcFare, calcFareByDistance, FareResult, TaxiType, FARE_DISCLAIMER, ROUTE_FACTOR, calcDistanceKm, formatDate, formatTime, haversineKm, interpolateLatLng, estimateFare, estimateRoadDistanceKm, getDrivingDistanceKm, getDrivingRoute, positionAlongPath, getRealPosition, GEO_STATUS, latLngToSvg
import { logger } from '@/lib/standalone-shim';
import { MOCK_LANDMARKS, type TaxiZone } from '@/data/landmarks';

export const FARE_DISCLAIMER = '示範費率，以政府跳錶為準';

/** 道路距離估算系數（直線距離 × 系數 ≈ 實際道路距離，香港道路網平均約 1.5）
 *  香港地少山多、道路彎曲多、單行線多，實際行車距離通常比直線遠 40-60%。
 *  市區密集道路約 1.5-1.7，新界公路約 1.3-1.5，整體平均取 1.5。
 */
export const ROUTE_FACTOR = 1.5;

export type TaxiType = 'urban' | 'nt' | 'lantau';

/** 計算兩個經緯度點之間嘅直線距離（公里） */
export function haversineKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const R = 6371; // 地球半徑 km
  const dLat = ((b.lat - a.lat) * Math.PI) / 180;
  const dLng = ((b.lng - a.lng) * Math.PI) / 180;
  const lat1Rad = (a.lat * Math.PI) / 180;
  const lat2Rad = (b.lat * Math.PI) / 180;
  const h =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos(lat1Rad) * Math.cos(lat2Rad) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return 2 * R * Math.asin(Math.sqrt(h));
}

/**
 * 估算實際道路距離（公里）。
 * 優先使用高德 Driving 路線 API；攞唔到時用 haversine 直線距離 × ROUTE_FACTOR 兜底。
 *
 * 呢個函數係「兜底版本」，如果頁面度有 AMap SDK，會直接 call AMap.Driving 攞真實道路距離，
 * 結果失敗或者 SDK 未加載時先用呢度嘅估算。
 */
export function estimateRoadDistanceKm(
  a: { lat: number; lng: number },
  b: { lat: number; lng: number },
): number {
  const straight = haversineKm(a, b);
  return Math.max(0.5, straight * ROUTE_FACTOR);
}

const AMAP_KEY = '75e09e701f85fabf849e5ff5ef36c01f';
let amapReadyPromise: Promise<void> | null = null;

/**
 * 確保高德 JS SDK 連 AMap.Driving plugin 已加載就緒。
 * 解決「riding / 出單頁 recompute 路線時 SDK 未 ready → 跌咗去直線兜底 → 距離時間唔一致」問題。
 * AMapView 已加載過時 window.AMap 存在，只會等 Driving ready，唔會重複加 script。
 */
export function ensureAmapReady(): Promise<void> {
  if (amapReadyPromise) return amapReadyPromise;

  amapReadyPromise = new Promise((resolve) => {
    const waitDriving = () => {
      let tries = 0;
      const poll = () => {
        if (window.AMap?.Driving) {
          resolve();
          return;
        }
        // Driving plugin 未就緒，最多 poll 5 秒，超時都 resolve 等 caller 兜底
        tries += 1;
        if (tries > 50) {
          resolve();
          return;
        }
        setTimeout(poll, 100);
      };
      poll();
    };
    if (window.AMap) {
      waitDriving();
    } else {
      const script = document.createElement('script');
      script.async = true;
      script.src = `https://webapi.amap.com/maps?v=2.0&key=${AMAP_KEY}&plugin=AMap.Driving,AMap.AutoComplete,AMap.PlaceSearch,AMap.Geocoder`;
      script.onload = waitDriving;
      script.onerror = () => resolve(); // 失敗都 resolve，等 caller 用直線兜底
      document.head.appendChild(script);
    }
  });

  return amapReadyPromise;
}

/**
 * 用 OSRM（OpenStreetMap 免費路線服務）攞真實道路距離 + 時間 + 路徑。
 * 高德 Driving 需要「Web 服務」權限，key 未開通時會 fail；OSRM 免費無 key、香港 OSM 道路網完整，
 * 用嚟做路線後備，令距離/時間跟返真實道路而唔係直線估算。
 * 注意：OSRM 時間係按限速（無實時路況），比高德略偏理想，但距離係真實道路距離。
 */
export async function getOsrmRoute(
  origin: { lat: number; lng: number },
  destination: { lat: number; lng: number },
): Promise<{ distanceKm: number; durationSec: number; path: Array<[number, number]> }> {
  const url = `https://router.project-osrm.org/route/v1/driving/${origin.lng},${origin.lat};${destination.lng},${destination.lat}?overview=full&geometries=geojson&steps=false`;
  const res = await fetch(url);
  if (!res.ok) throw new Error('OSRM http ' + res.status);
  const data = await res.json();
  const route = data.routes?.[0];
  if (!route) throw new Error('OSRM no route');
  const coordinates: number[][] = route.geometry?.coordinates ?? [];
  const path: Array<[number, number]> = coordinates.map((c) => [c[0], c[1]] as [number, number]);
  if (path.length === 0) {
    path.push([origin.lng, origin.lat]);
    path.push([destination.lng, destination.lat]);
  }
  return {
    distanceKm: Math.max(0.05, route.distance / 1000),
    durationSec: Math.max(10, route.duration),
    path,
  };
}

/**
 * 用高德 AMap.Driving 拿真實道路距離（公里）。
 * 成功 resolve 距離；失敗 / SDK 未加載 reject，caller 用 estimateRoadDistanceKm 兜底。
 *
 * @param pickup 起點 { lat, lng }
 * @param destination 終點 { lat, lng }
 */
export async function getDrivingDistanceKm(
  pickup: { lat: number; lng: number },
  destination: { lat: number; lng: number },
): Promise<number> {
  await ensureAmapReady();
  return new Promise((resolve, reject) => {
    if (!window.AMap || !window.AMap.Driving) {
      reject(new Error('AMap.Driving not available'));
      return;
    }

    try {
      const driving = new window.AMap.Driving({
        map: null,
        panel: null,
        hideMarkers: true,
        autoFitView: false,
      });

      driving.search(
        [pickup.lng, pickup.lat],
        [destination.lng, destination.lat],
        (status: string, result: any) => {
          if (status === 'complete' && result.routes?.[0]) {
            // distance 係米，轉成公里
            const distanceKm = (result.routes[0].distance ?? 0) / 1000;
            if (distanceKm > 0) {
              resolve(Math.max(0.5, distanceKm));
              return;
            }
          }
          // 高德 Driving 無權限/失敗 → fallback 去 OSRM，最後先由 caller 用直線兜底
          getOsrmRoute(pickup, destination)
            .then((r) => resolve(r.distanceKm))
            .catch(() => reject(new Error('Driving route not found')));
        },
      );
    } catch (err) {
      reject(err);
    }
  });
}

/** 喺兩個經緯度對象之間插值 */
export function interpolateLatLng(
  start: { lat: number; lng: number },
  end: { lat: number; lng: number },
  t: number,
): { lat: number; lng: number } {
  return {
    lat: start.lat + (end.lat - start.lat) * t,
    lng: start.lng + (end.lng - start.lng) * t,
  };
}

/**
 * 用高德 AMap.Driving 拿完整路線（總距離 + 時間 + 路徑點數組）。
 * 路徑點用於模擬車輛沿真實道路移動。
 * 成功 resolve 結果；失敗 / SDK 未加載 reject，caller 用直線兜底。
 */
export async function getDrivingRoute(
  origin: { lat: number; lng: number },
  destination: { lat: number; lng: number },
): Promise<{
  distanceKm: number;
  durationSec: number;
  path: Array<[number, number]>; // [lng, lat]
}> {
  await ensureAmapReady();
  return new Promise((resolve, reject) => {
    if (!window.AMap || !window.AMap.Driving) {
      reject(new Error('AMap.Driving not available'));
      return;
    }

    try {
      const driving = new window.AMap.Driving({
        map: null,
        panel: null,
        hideMarkers: true,
        autoFitView: false,
        // 用實時路況策略，高速公路/深夜路段會自動用更快車速
        policy: window.AMap?.Driving?.LEAST_TIME ?? 0,
      });

      driving.search(
        [origin.lng, origin.lat],
        [destination.lng, destination.lat],
        (status: string, result: any) => {
          if (status === 'complete' && result.routes?.[0]) {
            const route = result.routes[0];
            const distanceKm = Math.max(0.05, (route.distance ?? 0) / 1000);
            // 時間優先級：
            // 1. route.time — 高德建議總行車時間（秒，已計算路況同紅綠燈）
            // 2. 累加 steps.time — 分段時間加總
            // 3. 兜底：用總距離 ÷ 60 km/h（高速公路默認速度，比市區 30km/h 合理好多）
            let durationSec = route.time ?? 0;
            if (!durationSec && route.steps?.length > 0) {
              durationSec = route.steps.reduce((acc: number, s: any) => acc + (s.time ?? 0), 0);
            }
            if (!durationSec) {
              // 兜底：高速公路/快速路預計車速 60 km/h（香港公路常見速度）
              durationSec = (distanceKm / 60) * 3600;
            }
            durationSec = Math.max(10, durationSec);
            // steps 入面嘅 path 係 [[lng, lat], ...]
            const path: Array<[number, number]> = [];
            if (route.steps && route.steps.length > 0) {
              route.steps.forEach((step: any) => {
                if (step.path && step.path.length > 0) {
                  path.push(...step.path);
                }
              });
            }
            // 兜底：冇 steps 就用起終點當直線
            if (path.length === 0) {
              path.push([origin.lng, origin.lat]);
              path.push([destination.lng, destination.lat]);
            }
            resolve({ distanceKm, durationSec, path });
          } else {
            // 高德 Driving 無權限/失敗 → fallback 去 OSRM，最後先由 caller 用直線兜底
            getOsrmRoute(origin, destination)
              .then((r) => resolve(r))
              .catch(() => reject(new Error('Driving route not found')));
          }
        },
      );
    } catch (err) {
      reject(err);
    }
  });
}

/**
 * 沿路徑點累進距離前進，攞到指定累積距離（公里）對應嘅坐標。
 * 路徑點數組係 [lng, lat] 格式。
 * 用於模擬車輛沿真實道路逐步移動。
 */
export function positionAlongPath(
  path: Array<[number, number]>,
  distanceKm: number,
): { lat: number; lng: number } {
  if (path.length === 0) return { lat: 22.3, lng: 114.17 };
  if (path.length === 1) return { lat: path[0][1], lng: path[0][0] };

  let acc = 0; // 累積距離 km
  for (let i = 1; i < path.length; i++) {
    const prev = path[i - 1];
    const curr = path[i];
    const segLen = haversineKm(
      { lat: prev[1], lng: prev[0] },
      { lat: curr[1], lng: curr[0] },
    );
    if (acc + segLen >= distanceKm) {
      const t = segLen === 0 ? 0 : (distanceKm - acc) / segLen;
      return {
        lng: prev[0] + (curr[0] - prev[0]) * t,
        lat: prev[1] + (curr[1] - prev[1]) * t,
      };
    }
    acc += segLen;
  }
  // 超過總長就返終點
  const last = path[path.length - 1];
  return { lat: last[1], lng: last[0] };
}

/** 定位狀態 */
export const GEO_STATUS = {
  IDLE: 'idle',
  LOADING: 'loading',
  SUCCESS: 'success',
  DENIED: 'denied',
  UNAVAILABLE: 'unavailable',
} as const;
export type GeoStatus = typeof GEO_STATUS[keyof typeof GEO_STATUS];

/**
 * 用瀏覽器 geolocation 攞司機真實位置。
 * 成功 resolve 座標；失敗 reject 並告知原因（用戶拒絕／瀏覽器唔支援等）。
 * caller 收到失敗就可以切去模擬兜底。
 */
export function getRealPosition(
  enableHighAccuracy = true,
  timeoutMs = 8000,
): Promise<{ lat: number; lng: number; accuracy: number }> {
  return new Promise((resolve, reject) => {
    if (!('geolocation' in navigator)) {
      reject(new Error('geolocation not supported'));
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude, accuracy } = pos.coords;
        logger.info('got real position:', { lat: latitude, lng: longitude, accuracy });
        resolve({ lat: latitude, lng: longitude, accuracy });
      },
      (err) => {
        logger.warn('geolocation error:', String(err?.code ?? 'unknown'));
        reject(err);
      },
      { enableHighAccuracy, timeout: timeoutMs, maximumAge: 5000 },
    );
  });
}

/** 格式化日期為 YYYY/MM/DD */
export function formatDate(ts: number): string {
  const d = new Date(ts);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}/${m}/${day}`;
}

/** 格式化時間為 HH:mm */
export function formatTime(ts: number): string {
  const d = new Date(ts);
  const h = String(d.getHours()).padStart(2, '0');
  const m = String(d.getMinutes()).padStart(2, '0');
  return `${h}:${m}`;
}

/** 簡易車費估算（舊 API，用於向後兼容；建議改用 calcFare）
 *  註：呢度接收嘅 distanceKm 係直線距離，會自動乘 ROUTE_FACTOR 變道路距離先計費。
 */
export function estimateFare(
  straightDistanceKm: number,
  _carType: '4-seater' | '6-seater' = '4-seater',
): number {
  const distanceKm = Math.max(0.5, straightDistanceKm * ROUTE_FACTOR);
  const baseFare = 29;
  const per200m = 1.9;
  const remainingKm = Math.max(0, distanceKm - 2);
  const num200m = Math.ceil((remainingKm * 1000) / 200);
  return Math.round(baseFare + num200m * per200m);
}

