/** 用地標名稱找 zone */
function findZone(name: string): TaxiZone {
  const lm = MOCK_LANDMARKS.find((l) => l.name === name);
  return lm?.zone ?? 'urban';
}

/** 將經緯度轉換為 SVG canvas 坐標 */
export function latLngToSvg(
  lat: number,
  lng: number,
  bounds: { minLat: number; maxLat: number; minLng: number; maxLng: number },
  width: number,
  height: number,
): { x: number; y: number } {
  const x = ((lng - bounds.minLng) / (bounds.maxLng - bounds.minLng)) * width;
  const y = ((bounds.maxLat - lat) / (bounds.maxLat - bounds.minLat)) * height;
  return { x, y };
}

/** 用名稱搵地標計算直線距離，再乘以路線係數（1.5 為香港道路網平均估算） */
export function calcDistanceKm(pickup: string, destination: string): number {
  const p = MOCK_LANDMARKS.find((l) => l.name === pickup);
  const d = MOCK_LANDMARKS.find((l) => l.name === destination);
  if (!p || !d) return 3.0;
  const straight = haversineKm(p, d);
  // 香港道路網實際行車距離約為直線 1.3-1.7 倍
  return Math.max(0.5, straight * ROUTE_FACTOR);
}

/**
 * 用「道路距離」直接計費（避免重複乘 ROUTE_FACTOR）。
 * 公式：起步價 + (道路距離 - 起步里程) ÷ 200m × 每跳金額 + 附加費 + 貼士
 *
 * @param roadDistanceKm 真實道路距離（公里），**唔可以再乘 ROUTE_FACTOR**
 * @param taxiType 'urban' | 'nt' | 'lantau'
 * @param options.tip 貼士
 * @param options.luggageCount 行李件數
 * @param options.waitingMinutes 等候分鐘
 * @param options.tunnelSurcharge 隧道費
 * @param options.isDirectDiscount 直出折扣：standard / discount85 / discount90 / discount95 / teishoku
 * @param options.teishokuPrice 定食直出價（teishoku 模式用）
 */
export function calcFareByDistance(
  roadDistanceKm: number,
  taxiType: TaxiType,
  options?: {
    tip?: number;
    luggageCount?: number;
    waitingMinutes?: number;
    tunnelSurcharge?: number;
    isDirectDiscount?: 'standard' | 'discount85' | 'discount90' | 'discount95' | 'teishoku';
    teishokuPrice?: number;
  },
): { total: number; breakdown: FareBreakdown; distanceKm: number } {
  const tip = options?.tip ?? 0;
  const luggage = options?.luggageCount ?? 0;
  const waitingMin = options?.waitingMinutes ?? 0;
  const tunnel = options?.tunnelSurcharge ?? 0;

  const rate = RATES[taxiType] ?? RATES.urban;
  const distanceKm = Math.max(0.5, roadDistanceKm);

  // 里程費：首 2 公里起表，其後每 200 米
  const remainingKm = Math.max(0, distanceKm - 2);
  const num200m = Math.ceil((remainingKm * 1000) / 200);
  const mileageFare = num200m * rate.per200m;

  // 等候費
  const waitingFare = Math.ceil(waitingMin) * rate.waitingPerMin;

  // 行李附加費
  let luggageSurcharge = 0;
  if (luggage > 0) {
    luggageSurcharge = rate.firstBaggage + Math.max(0, luggage - 1) * (rate.perExtraBaggage ?? rate.firstBaggage);
  }

  const subtotal = rate.flagfall + mileageFare + waitingFare + luggageSurcharge + tunnel;

  // 直出折扣：85/90/95 折；teishoku 用固定價
  let total: number;
  if (options?.isDirectDiscount === 'teishoku') {
    total = Math.round((options.teishokuPrice ?? 0) + tip);
  } else if (options?.isDirectDiscount === 'discount85') {
    total = Math.round(subtotal * 0.85 + tip);
  } else if (options?.isDirectDiscount === 'discount90') {
    total = Math.round(subtotal * 0.9 + tip);
  } else if (options?.isDirectDiscount === 'discount95') {
    total = Math.round(subtotal * 0.95 + tip);
  } else {
    total = Math.round(subtotal + tip);
  }

  return {
    total,
    breakdown: {
      flagfall: rate.flagfall,
      mileageFare: Number(mileageFare.toFixed(1)),
      waitingFare: Number(waitingFare.toFixed(1)),
      luggageSurcharge: Number(luggageSurcharge.toFixed(1)),
      tunnelSurcharge: tunnel,
      tip,
    },
    distanceKm,
  };
}

/**
 * 計算的士車費（根據地名自動搵座標 + 估算道路距離）
 * @param pickup 上車地點名稱
 * @param destination 目的地名稱
 * @param carType '4-seater' | '6-seater'
 * @param options.tip 貼士金額
 * @param options.luggageCount 行李件數
 * @param options.waitingMinutes 等候時間（分鐘）
 */
export function calcFare(
  pickup: string,
  destination: string,
  carType: '4-seater' | '6-seater',
  options?: {
    tip?: number;
    luggageCount?: number;
    waitingMinutes?: number;
    time?: Date;
  },
): FareResult {
  const tip = options?.tip ?? 0;
  const luggage = options?.luggageCount ?? 0;
  const waitingMin = options?.waitingMinutes ?? 0;

  // 判斷的士類型
  const pickupZone = findZone(pickup);
  const destZone = findZone(destination);

  let taxiType: TaxiType;
  // 4 人車同 6 人車跳錶收費一樣，6 人車唔可以有附加費（香港法例）
  const bothNT = pickupZone === 'new-territories' && destZone === 'new-territories';
  const bothLantau = pickupZone === 'lantau' && destZone === 'lantau';
  if (bothLantau) {
    taxiType = 'lantau';
  } else if (bothNT) {
    taxiType = 'nt';
  } else {
    taxiType = 'urban';
  }

  const rate = RATES[taxiType];
  // calcDistanceKm 已經係道路距離（內部乘咗 ROUTE_FACTOR），唔會再乘
  const distanceKm = calcDistanceKm(pickup, destination);

  // 隧道附加費：港島 ↔ 九龍 過海
  let tunnelSurcharge = 0;
  const pickupIsIsland = pickupZone === 'urban';
  const destIsIsland = destZone === 'urban';
  const pickupIsKowloon = pickupZone === 'urban'; // 示範：urban 同時包含港島同九龍
  const destIsKowloon = destZone === 'urban';
  // 用經度粗略判斷：港島 lng < 114.175，九龍 lng > 114.175
  const p = MOCK_LANDMARKS.find((l) => l.name === pickup);
  const d = MOCK_LANDMARKS.find((l) => l.name === destination);
  if (p && d) {
    const pIsHKI = p.lat < 22.3 && p.zone === 'urban'; // 港島
    const pIsKLN = p.lat >= 22.3 && p.zone === 'urban'; // 九龍
    const dIsHKI = d.lat < 22.3 && d.zone === 'urban';
    const dIsKLN = d.lat >= 22.3 && d.zone === 'urban';
    if ((pIsHKI && dIsKLN) || (pIsKLN && dIsHKI)) {
      // 過海：示範用紅隧收費
      tunnelSurcharge = rate.crossHarbourTunnel;
    }
  }
  // 避免 ts 未用警告
  void pickupIsIsland; void destIsIsland; void pickupIsKowloon; void destIsKowloon;

  // 用 calcFareByDistance 計算（統一邏輯，避免重複乘 ROUTE_FACTOR）
  const { total, breakdown } = calcFareByDistance(distanceKm, taxiType, {
    tip,
    luggageCount: luggage,
    waitingMinutes: waitingMin,
    tunnelSurcharge,
  });

  return {
    total,
    breakdown,
    taxiType,
    taxiTypeName: rate.name,
    taxiTypeColor: rate.color,
    distanceKm,
    waitingMinutes: waitingMin,
    carType,
  };
}
