import { User, Settings, MapPin, CreditCard, HelpCircle, ChevronRight, Star, Car, RotateCcw, LogOut } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { useState, useMemo, useEffect } from 'react';
import { useOrder } from '@/lib/order-context';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';
import { Image } from '@/components/ui/image';
import { useI18n } from '@/lib/i18n';

export default function PassengerProfilePage() {
  const navigate = useNavigate();
  const { resetDemoData, logout, user, isLoggedIn } = useOrder();
  const [showResetConfirm, setShowResetConfirm] = useState(false);
  const { t } = useI18n();

  // 登入守衛
  useEffect(() => {
    if (!isLoggedIn) {
      navigate('/passenger/login', { replace: true });
    }
  }, [isLoggedIn, navigate]);

  const menuItems = useMemo(() => [
    { icon: MapPin, label: t.passengerProfile.menu.addresses, value: t.passengerProfile.addressesCount },
    { icon: CreditCard, label: t.passengerProfile.menu.payment, value: t.passengerProfile.octopus },
    { icon: Star, label: t.passengerProfile.menu.coupons, value: t.passengerProfile.couponsCount },
    { icon: HelpCircle, label: t.passengerProfile.menu.help, value: '' },
    { icon: Settings, label: t.passengerProfile.menu.settings, value: '' },
  ], [t]);

  const handleLogout = () => {
    logout();
    navigate('/');
  };

  const handleReset = () => {
    resetDemoData();
    toast.success(t.passengerProfile.resetSuccess);
    setShowResetConfirm(false);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-sky-5 via-white to-slate-50 pb-24">
      {/* Profile header */}
      <div className="bg-gradient-to-br from-primary to-primary/80 text-primary-foreground px-4 pt-10 pb-16 rounded-b-3xl">
        <div className="flex items-center gap-4">
          <Avatar className="size-16 border-2 border-white/30">
            <AvatarImage
              src="https://lf3-static.bytednsdoc.com/obj/eden-cn/ylcylz_fsph_ryhs/ljhwZthlaukjlkulzlp/feisuda/avatar/base/1.jpg"
              alt="用戶"
            />
            <AvatarFallback>{(user?.name || t.passengerProfile.guest).charAt(0)}</AvatarFallback>
          </Avatar>
          <div className="flex-1">
            <h1 className="text-xl font-bold">{user?.name || t.passengerProfile.guest}</h1>
            <p className="text-sm opacity-80">{user?.phone || t.passengerProfile.member}</p>
          </div>
          <button className="size-9 rounded-full bg-white/20 flex items-center justify-center">
            <Settings className="size-5" />
          </button>
        </div>
      </div>

      {/* Stats card */}
      <div className="px-4 -mt-8">
        <Card className="shadow-lg">
          <CardContent className="p-4 grid grid-cols-3 divide-x divide-slate-100">
            <div className="text-center">
              <div className="text-2xl font-bold text-foreground">12</div>
              <div className="text-xs text-muted-foreground mt-0.5">{t.passengerProfile.totalTrips}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-foreground">HK$856</div>
              <div className="text-xs text-muted-foreground mt-0.5">{t.passengerProfile.totalSpent}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-amber-500">4.8</div>
              <div className="text-xs text-muted-foreground mt-0.5">{t.passengerProfile.avgRating}</div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Menu */}
      <div className="px-4 mt-6">
        <Card className="shadow-sm overflow-hidden">
          {menuItems.map((item, i) => {
            const Icon = item.icon;
            return (
              <button
                key={item.label}
                className={`w-full flex items-center gap-3 p-4 hover:bg-slate-50 transition-colors text-left ${
                  i !== 0 ? 'border-t border-slate-100' : ''
                }`}
              >
                <div className="size-9 rounded-full bg-primary/10 flex items-center justify-center">
                  <Icon className="size-4 text-primary" />
                </div>
                <span className="flex-1 text-sm font-medium text-foreground">
                  {item.label}
                </span>
                {item.value && (
                  <span className="text-xs text-muted-foreground">{item.value}</span>
                )}
                <ChevronRight className="size-4 text-slate-400" />
              </button>
            );
          })}
        </Card>
      </div>

      {/* Reset demo data */}
      <div className="px-4 mt-6">
        <button
          onClick={handleLogout}
          className="w-full flex items-center justify-center gap-2 p-4 rounded-xl bg-red-500/10 text-red-500 hover:bg-red-500/20 transition-colors mb-3"
        >
          <LogOut className="size-4" />
          <span className="text-sm font-medium">{t.passengerProfile.logoutBtn}</span>
        </button>

        <AlertDialog open={showResetConfirm} onOpenChange={setShowResetConfirm}>
          <AlertDialogTrigger asChild>
            <button className="w-full flex items-center justify-center gap-2 p-4 rounded-xl border border-slate-200 bg-white hover:bg-slate-50 transition-colors text-muted-foreground">
              <RotateCcw className="size-4" />
              <span className="text-sm font-medium">{t.passengerProfile.resetDemo}</span>
            </button>
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>{t.passengerProfile.resetTitle}</AlertDialogTitle>
              <AlertDialogDescription>
                {t.passengerProfile.resetDesc}
              </AlertDialogDescription>
            </AlertDialogHeader>
            <AlertDialogFooter>
              <AlertDialogCancel>{t.passengerProfile.cancel}</AlertDialogCancel>
              <AlertDialogAction onClick={handleReset} className="bg-destructive hover:bg-destructive/90">
                {t.passengerProfile.confirmReset}
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </div>

      {/* Promo */}
      <div className="px-4 mt-6">
        <div className="bg-gradient-to-r from-amber-50 to-orange-50 border border-amber-200/50 rounded-2xl p-4 flex items-center gap-3">
          <div className="size-12 rounded-xl bg-amber-400 flex items-center justify-center text-white">
            <Car className="size-6" />
          </div>
          <div className="flex-1">
            <div className="text-sm font-semibold text-amber-900">{t.passengerProfile.inviteTitle}</div>
            <div className="text-xs text-amber-700">{t.passengerProfile.inviteDesc}</div>
          </div>
          <ChevronRight className="size-4 text-amber-600" />
        </div>
      </div>

      {/* App info */}
      <div className="px-4 mt-8 mb-8 text-center">
        <div className="flex items-center justify-center gap-2 mb-2">
          <Image
            src="https://aka.doubaocdn.com/s/pKMrCCXYov"
            alt="的道"
            className="size-6 rounded-full object-cover"
          />
          <span className="text-sm font-semibold text-foreground">的道</span>
        </div>
        <div className="text-xs text-muted-foreground">{t.passengerProfile.version}</div>
      </div>
    </div>
  );
}
