import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Car, User, MapPin, Shield, Zap, Settings, Globe, ArrowRight, Key, Mail } from 'lucide-react';
import { toast } from 'sonner';
import { useTheme } from '@/lib/theme-context';
import { useI18n } from '@/lib/i18n';
import { Image } from '@/components/ui/image';
import PwaInstallPrompt from '@/components/PwaInstallPrompt';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from '@/components/ui/sheet';

const LOGO_URL = 'https://aka.doubaocdn.com/s/pKMrCCXYov';

export default function WelcomePage() {
  const navigate = useNavigate();
  const { theme, setTheme, primaryColor } = useTheme();
  const { t, lang, setLang } = useI18n();
  const [logoLoaded, setLogoLoaded] = useState(false);
  const [langSheetOpen, setLangSheetOpen] = useState(false);

  const handleStartPassenger = () => {
    toast.success(t.welcome.welcomePassenger);
    navigate('/passenger/login');
  };

  const handleStartDriver = () => {
    toast.success(t.welcome.welcomeDriver);
    navigate('/driver/login');
  };

  const handleRental = () => {
    navigate('/rental');
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-slate-50 via-white to-background text-foreground flex flex-col relative overflow-hidden">
      {/* 背景裝飾 - 柔和光斑 */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div
          className="absolute top-16 left-8 size-72 rounded-full blur-3xl"
          style={{ backgroundColor: primaryColor, opacity: 0.08 }}
        />
        <div className="absolute bottom-48 right-6 size-80 rounded-full bg-amber-300/20 blur-3xl" />
        <div className="absolute top-1/3 right-1/4 size-40 rounded-full bg-emerald-300/10 blur-2xl" />
      </div>

      {/* 頂部：主題切換 + 語言 */}
      <div className="relative z-10 pt-4 px-4 flex items-center gap-2">
          <div className="flex-1 flex items-center justify-center gap-4">
            <button
              onClick={() => setTheme('red')}
              className={`px-8 py-3.5 rounded-full text-xl font-bold transition-all ${
              theme === 'red'
                ? 'bg-red-500 text-white shadow-lg shadow-red-500/25'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
             {t.welcome.themeUrban}
          </button>
            <button
              onClick={() => setTheme('green')}
              className={`px-8 py-3.5 rounded-full text-xl font-bold transition-all ${
              theme === 'green'
                ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/25'
                : 'bg-muted text-muted-foreground hover:text-foreground'
            }`}
          >
             {t.welcome.themeNt}
          </button>
        </div>
        <Sheet open={langSheetOpen} onOpenChange={setLangSheetOpen}>
          <SheetTrigger asChild>
            <button className="size-9 rounded-full bg-card border border-border flex items-center justify-center hover:bg-muted transition-colors shrink-0 shadow-sm">
              <Globe className="size-4 text-muted-foreground" />
            </button>
          </SheetTrigger>
          <SheetContent side="bottom" className="rounded-t-3xl pb-8 bg-background text-foreground border-t border-border">
            <SheetHeader>
              <SheetTitle className="text-foreground">{t.language.title}</SheetTitle>
            </SheetHeader>
            <div className="px-5 pt-4 space-y-2">
              {(['zh-Hant', 'en', 'ja'] as const).map((l) => (
                <button
                  key={l}
                  onClick={() => {
                    setLang(l);
                    setLangSheetOpen(false);
                  }}
                  className={`w-full flex items-center justify-between p-4 rounded-2xl border-2 transition-all ${
                    lang === l
                      ? 'border-primary bg-primary/5'
                      : 'border-border hover:border-muted-foreground/30'
                  }`}
                >
                  <span className={`font-medium ${lang === l ? 'text-primary' : 'text-foreground'}`}>
                    {t.language[l === 'zh-Hant' ? 'zhHant' : l]}
                  </span>
                  {lang === l && (
                    <div className="size-5 rounded-full bg-primary flex items-center justify-center">
                      <svg className="size-3 text-primary-foreground" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                        <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                      </svg>
                    </div>
                  )}
                </button>
              ))}
            </div>
          </SheetContent>
        </Sheet>
      </div>

      {/* 主內容 */}
      <div className="relative z-10 flex-1 flex flex-col items-center justify-center px-6 pt-6 pb-8">
        {/* Logo */}
        <motion.div
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, ease: 'easeOut' }}
          className="mb-6"
        >
          <div
            className="relative size-32 md:size-40 rounded-full overflow-hidden shadow-xl ring-4 ring-white"
            style={{ boxShadow: `0 20px 50px ${primaryColor}25` }}
          >
            {!logoLoaded && (
              <div className="absolute inset-0 bg-muted animate-pulse flex items-center justify-center">
                <Car className="size-12 text-muted-foreground/40" />
              </div>
            )}
            <Image
              src={LOGO_URL}
              alt="Logo"
              className={`w-full h-full object-cover transition-opacity duration-500 ${
                logoLoaded ? 'opacity-100' : 'opacity-0'
              }`}
              onLoad={() => setLogoLoaded(true)}
            />
          </div>
        </motion.div>

        {/* 品牌名 */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.2, ease: 'easeOut' }}
          className="text-center mb-2"
        >
          <h1 className="text-4xl md:text-5xl font-black tracking-tight text-foreground">
            的<span style={{ color: primaryColor }}>道</span>
          </h1>
        </motion.div>

        {/* 簡介 */}
        <motion.p
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.6, delay: 0.35 }}
          className="text-muted-foreground text-sm md:text-base mb-10 text-center max-w-xs"
        >
          {t.welcome.tagline}
        </motion.p>

        {/* 特色亮點 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.5 }}
          className="grid grid-cols-3 gap-4 mb-12 w-full max-w-sm"
        >
          {[
            { icon: Zap, label: t.welcome.features.instant },
            { icon: Shield, label: t.welcome.features.safe },
            { icon: MapPin, label: t.welcome.features.track },
          ].map((item) => {
            const Icon = item.icon;
            return (
              <div
                key={item.label}
                className="flex flex-col items-center gap-2"
              >
                <div className="size-12 rounded-2xl bg-card border border-border flex items-center justify-center shadow-sm">
                  <Icon className="size-5" style={{ color: primaryColor }} />
                </div>
                <span className="text-xs text-muted-foreground text-center">{item.label}</span>
              </div>
            );
          })}
        </motion.div>

        {/* 入口按鈕 */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.6, delay: 0.65 }}
          className="w-full max-w-sm space-y-3"
        >
          <button
             onClick={handleStartPassenger}
             className="w-full h-14 rounded-2xl text-primary-foreground font-bold text-base shadow-lg hover:scale-[1.02] active:scale-[0.98] transition-transform flex items-center justify-center gap-2 bg-primary"
             style={{ boxShadow: `0 10px 30px ${primaryColor}40` }}
           >
             <User className="size-5" />
             {t.welcome.startPassenger}
             <ArrowRight className="size-4 ml-1 opacity-80" />
           </button>

           {/* 司機 + 租車 並排 */}
           <div className="flex gap-3">
            <button
              onClick={handleStartDriver}
              className="flex-1 h-14 rounded-2xl bg-card border border-border text-foreground font-semibold text-base hover:bg-muted active:bg-accent transition-colors flex items-center justify-center gap-2 shadow-sm"
            >
              <Car className="size-5" style={{ color: primaryColor }} />
              {t.welcome.startDriver}
            </button>

            <button
              onClick={handleRental}
              className="w-14 h-14 rounded-2xl bg-card border border-border font-bold text-base hover:bg-muted active:bg-accent transition-colors flex flex-col items-center justify-center gap-0.5 shadow-sm shrink-0"
              aria-label="Rental"
            >
              <Key className="size-5" style={{ color: primaryColor }} />
              <span className="text-xs text-foreground font-semibold">租</span>
            </button>
           </div>

           <button
             onClick={() => navigate('/admin/login')}
             className="w-full h-11 rounded-2xl text-sm text-muted-foreground hover:text-foreground hover:bg-muted transition-all flex items-center justify-center gap-2"
           >
            <Settings className="size-4" />
            {t.welcome.adminEntry}
          </button>

          {/* 聯絡 */}
          <a
            href="mailto:tkdw0712@gmail.com"
            className="w-full h-11 rounded-2xl text-sm text-muted-foreground hover:text-foreground hover:bg-muted transition-all flex items-center justify-center gap-2"
          >
            <Mail className="size-4" />
            聯絡 · tkdw0712@gmail.com
          </a>
        </motion.div>
      </div>

      {/* 底部版權 */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6, delay: 0.9 }}
        className="relative z-10 text-center pb-6 text-xs text-muted-foreground"
      >
        {t.welcome.copyright}
      </motion.div>

      {/* PWA 安裝提示（歡迎頁模式：一打開就顯示） */}
      <PwaInstallPrompt mode="welcome" />


    </div>
  );
}
