import { useEffect, useState } from 'react';
import { testBackendConnection } from '@/lib/api';

/**
 * 雲端連線狀態徽章（全 App 右下角小顯示）
 * 綠點＝已連到雲端後端（真互通）；灰點＝離線單機模式（淨係自己部機玩）
 * 每 15 秒自動檢查一次
 */
export default function BackendStatusBadge() {
  const [state, setState] = useState<'checking' | 'online' | 'offline'>('checking');

  useEffect(() => {
    let alive = true;
    const check = async () => {
      const ok = await testBackendConnection();
      if (alive) setState(ok ? 'online' : 'offline');
    };
    check();
    const t = setInterval(check, 15000);
    return () => {
      alive = false;
      clearInterval(t);
    };
  }, []);

  if (state === 'checking') return null;

  return (
    <div
      className={`fixed bottom-16 right-2 z-[8990] flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold text-white shadow-lg ${
        state === 'online' ? 'bg-emerald-500/90' : 'bg-zinc-600/90'
      }`}
      title={state === 'online' ? '已連到雲端後端，兩部機互通正常' : '離線單機模式：冇連到雲端，訂單只喺呢部機'}
    >
      <span
        className={`size-1.5 rounded-full ${
          state === 'online' ? 'bg-white' : 'bg-amber-300'
        }`}
      />
      {state === 'online' ? '雲端已連接' : '離線單機'}
    </div>
  );
}
