import { useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, BellRing, CheckCheck, Car, CreditCard, Star, AlertCircle, Wallet, MessageSquare } from 'lucide-react';
import { useNotifications, type NotificationType } from '@/lib/notification-context';
import { useI18n } from '@/lib/i18n';
import { formatDistanceToNow } from 'date-fns';

type TabKey = 'all' | 'new_order' | 'order_status' | 'system' | 'rating';

const ICON_MAP: Record<NotificationType, typeof BellRing> = {
  new_order: Car,
  order_status: Car,
  system: AlertCircle,
  rating: Star,
  withdraw: Wallet,
  complaint: MessageSquare,
};

function getTypeColor(type: NotificationType): string {
  switch (type) {
    case 'new_order':
    case 'order_status':
      return 'text-primary bg-primary/10';
    case 'system':
      return 'text-info bg-info/10';
    case 'rating':
      return 'text-amber-600 bg-amber-50';
    case 'withdraw':
      return 'text-emerald-600 bg-emerald-50';
    case 'complaint':
      return 'text-destructive bg-destructive/10';
    default:
      return 'text-muted-foreground bg-muted';
  }
}

export default function NotificationsPage() {
  const navigate = useNavigate();
  const { notifications, markAsRead, markAllAsRead, unreadCount } = useNotifications();
  const { t, lang } = useI18n();
  const [tab, setTab] = useState<TabKey>('all');

  const tabs: { key: TabKey; label: string }[] = useMemo(
    () => [
      { key: 'all', label: t.notifications.tabAll },
      { key: 'new_order', label: t.notifications.newOrder },
      { key: 'order_status', label: t.notifications.orderStatus },
      { key: 'system', label: t.notifications.systemNotif },
      { key: 'rating', label: t.notifications.ratingNotif },
    ],
    [t],
  );

  const filtered = useMemo(() => {
    if (tab === 'all') return notifications;
    return notifications.filter((n) => n.type === (tab as NotificationType));
  }, [notifications, tab]);

  const formatTime = (ts: number) => {
    try {
      return formatDistanceToNow(ts, { addSuffix: true, locale: lang === 'zh-Hant' ? undefined : undefined });
    } catch {
      return new Date(ts).toLocaleString();
    }
  };

  return (
    <div className="min-h-screen bg-background pb-20">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-background/80 backdrop-blur-md border-b border-border/40">
        <div className="max-w-md mx-auto px-4 h-14 flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="size-9 rounded-full hover:bg-muted flex items-center justify-center shrink-0"
            aria-label="Back"
          >
            <ArrowLeft className="size-5 text-foreground" />
          </button>
          <h1 className="text-lg font-semibold flex-1">{t.notifications.title}</h1>
          {unreadCount > 0 && (
            <button
              onClick={markAllAsRead}
              className="text-sm text-primary font-medium flex items-center gap-1"
            >
              <CheckCheck className="size-4" />
              {t.notifications.markAllRead}
            </button>
          )}
        </div>

        {/* Tabs */}
        <div className="max-w-md mx-auto px-2 flex gap-1 overflow-x-auto pb-2 scrollbar-hide">
          {tabs.map((item) => (
            <button
              key={item.key}
              onClick={() => setTab(item.key)}
              className={`shrink-0 px-4 py-2 rounded-full text-sm font-medium transition-all ${
                tab === item.key
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground hover:text-foreground'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      </div>

      {/* List */}
      <div className="max-w-md mx-auto px-4 py-3 space-y-2">
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="size-16 rounded-full bg-muted flex items-center justify-center mb-4">
              <BellRing className="size-8 text-muted-foreground" />
            </div>
            <p className="text-base font-medium text-foreground">{t.notifications.empty}</p>
            <p className="text-sm text-muted-foreground mt-1">{t.notifications.emptyDesc}</p>
          </div>
        ) : (
          filtered.map((n) => {
            const Icon = ICON_MAP[n.type] ?? BellRing;
            return (
              <button
                key={n.id}
                onClick={() => markAsRead(n.id)}
                className={`w-full text-left p-4 rounded-2xl border transition-all ${
                  n.read
                    ? 'bg-card/50 border-border/40'
                    : 'bg-card border-primary/30 shadow-sm'
                }`}
              >
                <div className="flex gap-3">
                  <div className={`size-10 rounded-full flex items-center justify-center shrink-0 ${getTypeColor(n.type)}`}>
                    <Icon className="size-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <p className={`font-medium ${n.read ? 'text-muted-foreground' : 'text-foreground'}`}>
                        {n.title || getDefaultTitle(n.type, t)}
                      </p>
                      {!n.read && <span className="size-2 rounded-full bg-primary shrink-0 mt-1.5" />}
                    </div>
                    <p className={`text-sm mt-1 line-clamp-2 ${n.read ? 'text-muted-foreground' : 'text-foreground/80'}`}>
                      {n.content || getDefaultContent(n.type, t)}
                    </p>
                    <p className="text-xs text-muted-foreground mt-2">{formatTime(n.createdAt)}</p>
                  </div>
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

function getDefaultTitle(type: NotificationType, t: any): string {
  switch (type) {
    case 'new_order':
      return t.notifications.newOrder;
    case 'order_status':
      return t.notifications.orderStatus;
    case 'system':
      return t.notifications.systemNotif;
    case 'rating':
      return t.notifications.ratingNotif;
    case 'withdraw':
      return '提現';
    case 'complaint':
      return '投訴';
    default:
      return '';
  }
}

function getDefaultContent(type: NotificationType, t: any): string {
  switch (type) {
    case 'new_order':
      return t.notifications.newOrderFrom?.replace('{pickup}', '—').replace('{dest}', '—') || '';
    case 'system':
      return t.notifications.systemUpdateDesc || '';
    case 'rating':
      return t.notifications.ratingReceived || '';
    default:
      return '';
  }
}
