// 4 大導航 App 品牌標誌（SVG）
// 高德 / Google Maps / Waze / Apple Maps

export function AmapLogo({ className = 'size-6' }: { className?: string }) {
  // 高德地圖：藍色底 + 白色紙飛機/箭嘴
  return (
    <svg viewBox="0 0 48 48" className={className} aria-hidden="true">
      <defs>
        <linearGradient id="amapBg" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#1677FF" />
          <stop offset="100%" stopColor="#0052D9" />
        </linearGradient>
      </defs>
      <circle cx="24" cy="24" r="22" fill="url(#amapBg)" />
      <path
        d="M24 10 L34 30 L26 28 L24 36 L22 28 L14 30 Z"
        fill="#fff"
        stroke="#fff"
        strokeWidth="1"
        strokeLinejoin="round"
      />
      <circle cx="24" cy="22" r="3" fill="#1677FF" />
    </svg>
  );
}

export function GoogleMapsLogo({ className = 'size-6' }: { className?: string }) {
  // Google Maps：彩色地圖大头針
  return (
    <svg viewBox="0 0 48 48" className={className} aria-hidden="true">
      <defs>
        <linearGradient id="gmapPin" x1="0%" y1="0%" x2="0%" y2="100%">
          <stop offset="0%" stopColor="#EA4335" />
          <stop offset="100%" stopColor="#C5221F" />
        </linearGradient>
      </defs>
      <circle cx="24" cy="24" r="22" fill="#fff" />
      {/* 大头針 */}
      <path
        d="M24 8 C16 8 10 14 10 22 C10 30 17 37 24 40 C31 37 38 30 38 22 C38 14 32 8 24 8 Z"
        fill="url(#gmapPin)"
      />
      {/* 中間綠色圓點 */}
      <circle cx="24" cy="20" r="6" fill="#34A853" />
      {/* 白色高光 */}
      <ellipse cx="21" cy="16" rx="3" ry="2" fill="#fff" opacity="0.4" />
      {/* 底部地圖紋路（簡化） */}
      <path d="M14 28 L20 26 M28 26 L34 28" stroke="#FBBC04" strokeWidth="1.5" strokeLinecap="round" opacity="0.6" />
    </svg>
  );
}

