import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Star, Send, User } from 'lucide-react';
import { useOrder } from '@/lib/order-context';
import { useI18n } from '@/lib/i18n';
import { scopedStorage, logger } from '@/lib/standalone-shim';
import { toast } from 'sonner';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';

interface IRatingReply {
  orderId: string;
  reply: string;
  createdAt: number;
}

const STORAGE_KEY = 'hktaxi_driverRatingReplies';

function loadReplies(): Record<string, IRatingReply> {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) return JSON.parse(raw);
  } catch (e) {
    logger.error('load rating replies failed:', String(e));
  }
  return {};
}

function saveReplies(data: Record<string, IRatingReply>) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(data));
  } catch (e) {
    logger.error('save rating replies failed:', String(e));
  }
}

export default function DriverRatingListPage() {
  const navigate = useNavigate();
  const { historyOrders } = useOrder();
  const { t } = useI18n();
  const [replies, setReplies] = useState<Record<string, IRatingReply>>(() => loadReplies());
  const [replyDrafts, setReplyDrafts] = useState<Record<string, string>>({});

  // 有評分的歷史訂單（有 passengerRating）
  const ratedOrders = useMemo(
    () =>
      historyOrders
        .filter((o) => o.passengerRating && o.passengerRating > 0)
        .sort((a, b) => b.createdAt - a.createdAt),
    [historyOrders],
  );

  const handleSaveReply = (orderId: string) => {
    const text = (replyDrafts[orderId] || '').trim();
    if (!text) return;
    const newReply: IRatingReply = { orderId, reply: text, createdAt: Date.now() };
    const next = { ...replies, [orderId]: newReply };
    setReplies(next);
    saveReplies(next);
    setReplyDrafts((prev) => {
      const { [orderId]: _, ...rest } = prev;
      return rest;
    });
    toast.success(t.driverProfile.ratingReplySaved);
  };

  return (
    <div className="min-h-screen bg-background pb-10">
      {/* Header */}
      <div className="sticky top-0 z-40 bg-background/80 backdrop-blur-md border-b border-border/40">
        <div className="max-w-md mx-auto px-4 h-14 flex items-center gap-3">
          <button
            onClick={() => navigate(-1)}
            className="size-9 rounded-full hover:bg-muted flex items-center justify-center shrink-0"
            aria-label="Back"
          >
            <ArrowLeft className="size-5 text-foreground" />
          </button>
          <h1 className="text-lg font-semibold flex-1">{t.driverProfile.ratingListTitle}</h1>
        </div>
      </div>

      <div className="max-w-md mx-auto px-4 py-4 space-y-3">
        {ratedOrders.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-20 text-center">
            <div className="size-16 rounded-full bg-muted flex items-center justify-center mb-4">
              <Star className="size-8 text-muted-foreground" />
            </div>
            <p className="text-base font-medium text-foreground">{t.driverProfile.ratingListEmpty}</p>
            <p className="text-sm text-muted-foreground mt-1">{t.driverProfile.ratingListEmptyDesc}</p>
          </div>
        ) : (
          ratedOrders.map((order) => {
            const reply = replies[order.id];
            const draft = replyDrafts[order.id] ?? '';
            const passengerName = order.passenger?.name || '乘客';
            return (
              <div key={order.id} className="bg-card rounded-2xl border border-border/50 p-4 space-y-3">
                <div className="flex items-center gap-3">
                  <div className="size-10 rounded-full bg-muted flex items-center justify-center shrink-0">
                    <User className="size-5 text-muted-foreground" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-foreground truncate">{passengerName}</p>
                    <div className="flex items-center gap-1 mt-0.5">
                      {Array.from({ length: 5 }).map((_, i) => (
                        <Star
                          key={i}
                          className={`size-3.5 ${
                            i < (order.passengerRating || 0)
                              ? 'fill-amber-400 text-amber-400'
                              : 'text-slate-200'
                          }`}
                        />
                      ))}
                    </div>
                  </div>
                  {reply && (
                    <span className="text-[11px] px-2 py-1 rounded-full bg-emerald-50 text-emerald-600 font-medium shrink-0">
                      {t.driverProfile.ratingReplied}
                    </span>
                  )}
                </div>

                {order.passengerRatingTags && order.passengerRatingTags.length > 0 && (
                  <div className="flex flex-wrap gap-1.5">
                    {order.passengerRatingTags.map((tag) => (
                      <span
                        key={tag}
                        className="text-xs px-2 py-0.5 rounded-full bg-muted text-muted-foreground"
                      >
                        {tag}
                      </span>
                    ))}
                  </div>
                )}

                {/* 已回覆 */}
                {reply && (
                  <div className="pl-3 border-l-2 border-primary/30">
                    <p className="text-xs text-muted-foreground mb-1">{t.driverProfile.ratingReplyLabel}</p>
                    <p className="text-sm text-foreground leading-relaxed">{reply.reply}</p>
                  </div>
                )}

                {/* 回覆輸入 */}
                {!reply && (
                  <div className="space-y-2">
                    <Textarea
                      value={draft}
                      onChange={(e) =>
                        setReplyDrafts((prev) => ({ ...prev, [order.id]: e.target.value }))
                      }
                      placeholder={t.driverProfile.ratingReplyPlaceholder}
                      className="min-h-[80px] text-sm resize-none"
                    />
                    <div className="flex justify-end">
                      <Button
                        size="sm"
                        onClick={() => handleSaveReply(order.id)}
                        disabled={!draft.trim()}
                        className="gap-1.5"
                      >
                        <Send className="size-3.5" />
                        {t.driverProfile.ratingReplySubmit}
                      </Button>
                    </div>
                  </div>
                )}
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}
