import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { MapPin, Navigation, Clock, Star, X, Receipt, MessageCircle, MessageSquare, FileText } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Avatar, AvatarImage, AvatarFallback } from '@/components/ui/avatar';
import VvipBadge from '@/components/VvipBadge';
import { useI18n } from '@/lib/i18n';
import * as api from '@/lib/api';
import { useOrder, CAR_MODEL_OPTIONS, NOTE_TAG_OPTIONS } from '@/lib/order-context';
import ReceiptModal, { type ReceiptData } from '@/components/ReceiptModal';

interface IChatMessage {
  id: string;
  text: string;
  from: 'passenger' | 'driver';
  timestamp: number;
}

interface IHistoryItem {
  id: string;
  pickup: { name: string };
  destination: { name: string };
  estimatedFare: number;
  actualFare?: number;
  driver?: { name: string; imageUrl: string; rating: number; isVvip?: boolean; plate?: string; carModel?: string };
  createdAt: number;
  driverRating?: number;
  passengerRating?: number;
  status: string;
  carType: string;
  carModel?: string;
  passengerNotes?: { tags: string[]; text?: string };
  messages?: IChatMessage[];
  tip?: number;
  receiptNo?: string;
  paidAt?: number;
  paymentMethod?: string;
  distanceKm?: number;
  complaint?: { type: string; description: string; status: string; createdAt: number; reply?: string };
}

export default function PassengerHistoryPage() {
  const navigate = useNavigate();
  const { isLoggedIn } = useOrder();
  const [history, setHistory] = useState<IHistoryItem[]>([]);
  const [selected, setSelected] = useState<IHistoryItem | null>(null);
  const [loading, setLoading] = useState(true);
  const { t } = useI18n();
  const [receiptOpen, setReceiptOpen] = useState(false);
  const [receiptData, setReceiptData] = useState<ReceiptData | null>(null);

  // 登入守衛
  useEffect(() => {
    if (!isLoggedIn) {
      navigate('/passenger/login', { replace: true });
    }
  }, [isLoggedIn, navigate]);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      try {
        const orders = await api.getPassengerHistory();
        if (cancelled) return;
        const mapped: IHistoryItem[] = orders.map((o) => ({
          id: o.id,
          pickup: { name: o.pickupName },
          destination: { name: o.destinationName },
          estimatedFare: o.estimatedFare,
          actualFare: o.actualFare ?? undefined,
          driver: o.driverName
            ? {
                name: o.driverName,
                imageUrl: o.driverImageUrl ?? '',
                rating: o.driverRating ?? 5,
                isVvip: !!o.driverIsVvip,
                plate: o.driverPlate ?? undefined,
                carModel: o.driverCarModel ?? undefined,
              }
            : undefined,
          createdAt: new Date(o.createdAt).getTime(),
          driverRating: o.driverRating ?? undefined,
          passengerRating: o.passengerRating ?? undefined,
          status: o.status,
          carType: o.carType,
          carModel: o.carModel ?? undefined,
          passengerNotes: o.passengerNotes ?? undefined,
          messages: [],
          tip: o.tip ?? 0,
          receiptNo: o.receiptNo ?? undefined,
          paidAt: o.paidAt ?? undefined,
          paymentMethod: o.paymentMethod ?? undefined,
          distanceKm: o.distanceKm ?? undefined,
          complaint: o.complaint ?? undefined,
        }));
        setHistory(mapped);
      } catch {
        setHistory([]);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    load();
    return () => {
      cancelled = true;
    };
  }, []);

  const loadDetail = async (item: IHistoryItem) => {
    try {
      const msgs = await api.getOrderMessages(item.id);
      const chatMsgs: IChatMessage[] = msgs.map((m) => ({
        id: m.id,
        text: m.text,
        from: m.senderRole as 'passenger' | 'driver',
        timestamp: new Date(m.createdAt).getTime(),
      }));
      setSelected({ ...item, messages: chatMsgs });
    } catch {
      setSelected(item);
    }
  };

  const formatDate = (ts: number) => {
    const d = new Date(ts);
    return t.common.dateFormat.replace('{month}', String(d.getMonth() + 1)).replace('{day}', String(d.getDate()));
  };

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    return `${d.getHours().toString().padStart(2, '0')}:${d.getMinutes().toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-sky-50 via-white to-slate-50 pb-24">
      {/* Header */}
      <div className="px-4 pt-6 pb-4 sticky top-0 z-10 bg-white/80 backdrop-blur-md">
        <h1 className="text-2xl font-bold text-foreground">{t.passengerHistory.title}</h1>
        <p className="text-sm text-muted-foreground">{t.passengerHistory.count.replace('{count}', String(history.length))}</p>
      </div>

      {/* List */}
      <div className="px-4 space-y-3">
        {loading ? (
          <div className="text-center py-16">
            <div className="text-sm text-muted-foreground">{t.passengerHistory.loading}</div>
          </div>
        ) : history.length === 0 ? (
          <div className="text-center py-16">
            <div className="size-16 mx-auto mb-4 rounded-full bg-slate-100 flex items-center justify-center">
              <Receipt className="size-8 text-slate-400" />
            </div>
            <div className="text-foreground font-medium mb-1">{t.passengerHistory.empty}</div>
            <div className="text-sm text-muted-foreground">{t.passengerHistory.emptyDesc2}</div>
          </div>
        ) : (
          history.map((item, i) => (
            <motion.div
              key={item.id}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
            >
              <Card
                className="shadow-sm hover:shadow-md transition-shadow cursor-pointer"
                onClick={() => loadDetail(item)}
              >
                <CardContent className="p-4">
                  <div className="flex items-center justify-between mb-3">
                    <div className="text-xs text-muted-foreground">
                      {formatDate(item.createdAt)} {formatTime(item.createdAt)}
                    </div>
                    <Badge variant="outline" className="text-xs">
                      {item.status === 'finished' || item.status === 'paid' || item.status === 'completed'
                        ? t.passengerHistory.status.finished
                        : item.status === 'searching'
                        ? t.passengerHistory.status.searching || '尋找司機中'
                        : item.status === 'accepted'
                        ? t.passengerHistory.status.accepted || '司機已接單'
                        : item.status === 'picked_up'
                        ? t.passengerHistory.status.inProgress || '行程進行中'
                        : t.passengerHistory.status.finished}
                    </Badge>
                  </div>
                  <div className="flex items-start gap-3">
                    <div className="flex flex-col items-center pt-1">
                      <div className="size-2.5 rounded-full bg-emerald-500" />
                      <div className="w-px h-6 bg-slate-200 my-0.5" />
                      <div className="size-2.5 rounded-full bg-red-500" />
                    </div>
                    <div className="flex-1 min-w-0 space-y-1">
                      <div className="text-sm font-medium text-foreground truncate">
                        {item.pickup?.name || '上車點'}
                      </div>
                      <div className="text-sm font-medium text-foreground truncate">
                        {item.destination?.name || '目的地'}
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-lg font-bold text-primary">
                        HK${(item.actualFare ?? item.estimatedFare).toFixed(0)}
                      </div>
                      {item.driverRating ? (
                        <div className="flex items-center justify-end gap-0.5 mt-0.5">
                          <Star className="size-3 fill-amber-400 text-amber-400" />
                          <span className="text-xs text-amber-600">
                            {item.driverRating}
                          </span>
                        </div>
                      ) : (
                         <div className="text-xs text-muted-foreground mt-0.5">{t.passengerHistory.unrated}</div>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            </motion.div>
          ))
        )}
      </div>

      {/* Detail modal */}
      <AnimatePresence>
        {selected && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-end"
            onClick={() => setSelected(null)}
          >
            <motion.div
              initial={{ y: '100%' }}
              animate={{ y: 0 }}
              exit={{ y: '100%' }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              className="w-full bg-white rounded-t-3xl max-h-[80vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="p-5">
                <div className="flex items-center justify-between mb-5">
                  <h3 className="text-lg font-bold text-foreground">{t.passengerHistory.detailTitle}</h3>
                  <button
                    onClick={() => setSelected(null)}
                    className="size-8 rounded-full bg-slate-100 flex items-center justify-center"
                  >
                    <X className="size-4 text-slate-500" />
                  </button>
                </div>

                {selected.driver && (
                  <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-xl mb-4">
                    <Avatar className="size-12">
                      <AvatarImage
                        src={selected.driver?.imageUrl}
                        alt={selected.driver?.name || '司機'}
                      />
                      <AvatarFallback>{(selected.driver?.name || '司')[0]}</AvatarFallback>
                    </Avatar>
                    <div className="flex-1">
                      <div className="font-semibold text-foreground">
                        {selected.driver?.name || '司機'}
                        {selected.driver?.isVvip && (
                          <span className="ml-2"><VvipBadge size="sm" /></span>
                        )}
                      </div>
                      <div className="flex items-center gap-1 text-amber-500">
                        <Star className="size-3.5 fill-amber-400" />
                        <span className="text-sm">{selected.driver.rating}</span>
                      </div>
                    </div>
                    {selected.driverRating ? (
                      <div className="text-right">
                        {/* star rating display */}
                        <div className="flex items-center gap-0.5">
                          {[1, 2, 3, 4, 5].map((s) => (
                            <Star
                              key={s}
                              className={`size-4 ${
                                s <= (selected.driverRating ?? 0)
                                  ? 'fill-amber-400 text-amber-400'
                                  : 'text-slate-200'
                              }`}
                            />
                          ))}
                        </div>
                      </div>
                    ) : null}
                  </div>
                )}

                <div className="space-y-3 mb-4">
                  <div className="flex items-center gap-3">
                    <MapPin className="size-4 text-emerald-500 shrink-0" />
                    <div className="flex-1">
                       <div className="text-xs text-emerald-600">{t.passengerHistory.pickup}</div>
                      <div className="text-sm font-medium text-foreground">
                        {selected.pickup?.name || '上車點'}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-3">
                    <Navigation className="size-4 text-red-500 shrink-0" />
                    <div className="flex-1">
                       <div className="text-xs text-red-600">{t.passengerHistory.dropoff}</div>
                      <div className="text-sm font-medium text-foreground">
                        {selected.destination?.name || '目的地'}
                      </div>
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-2 gap-3 p-3 bg-slate-50 rounded-xl mb-4">
                  <div>
                     <div className="text-xs text-slate-500 mb-1">{t.passengerHistory.estimatedFare}</div>
                    <div className="font-semibold text-muted-foreground line-through">
                      HK${selected.estimatedFare.toFixed(0)}
                    </div>
                  </div>
                  <div>
                     <div className="text-xs text-slate-500 mb-1">{t.passengerHistory.actualFare}</div>
                    <div className="font-bold text-primary text-lg">
                      HK${(selected.actualFare ?? selected.estimatedFare).toFixed(0)}
                    </div>
                  </div>
                </div>

                {/* 車款 + 備注 */}
                <div className="p-3 bg-slate-50 rounded-xl mb-4">
                  <div className="flex items-center gap-2 mb-2">
                     <span className="text-xs text-slate-500">{t.passengerHistory.carTypeLabel}</span>
                    <span className="text-xs font-medium text-foreground">
                       {selected.carType === '6-seater' || selected.carType === '6pax' ? t.passengerHome.sixSeater : t.passengerHome.fourSeater}
                      {selected.carModel && ` · ${t.passengerHome.carModels[selected.carModel as keyof typeof t.passengerHome.carModels] ?? selected.carModel}`}
                    </span>
                  </div>
                  {selected.passengerNotes && (selected.passengerNotes.tags.length > 0 || selected.passengerNotes.text) && (
                    <div className="pt-2 border-t border-slate-200/60">
                      <div className="text-xs text-slate-500 mb-2 flex items-center gap-1">
                        <MessageSquare className="size-3" />
                        {t.passengerHome.passengerNotes}
                      </div>
                      {selected.passengerNotes.tags.length > 0 && (
                        <div className="flex flex-wrap gap-1 mb-2">
                          {selected.passengerNotes.tags.map((tag) => {
                            const opt = NOTE_TAG_OPTIONS.find((o) => o.value === tag);
                            return (
                              <Badge
                                key={tag}
                                variant="secondary"
                                className="text-[11px] bg-violet-50 text-violet-700 border-violet-200/50"
                              >
                                {opt?.emoji} {t.passengerHome.noteTags[tag as keyof typeof t.passengerHome.noteTags] ?? tag}
                              </Badge>
                            );
                          })}
                        </div>
                      )}
                      {selected.passengerNotes.text && (
                        <div className="text-xs text-foreground/80 bg-violet-50/50 p-2.5 rounded-lg">
                          {selected.passengerNotes.text}
                        </div>
                      )}
                    </div>
                  )}
                </div>

                <div className="p-3 bg-slate-50 rounded-xl mb-4">
                    <div className="text-xs text-slate-500 mb-2 flex items-center gap-1">
                      <Clock className="size-3" />
                      {t.passengerHistory.tripTime}
                    </div>
                  <div className="text-sm font-medium text-foreground">
                    {formatDate(selected.createdAt)} {formatTime(selected.createdAt)}
                  </div>
                </div>

                {/* 聊天記錄 */}
                {selected.messages && selected.messages.length > 0 && (
                  <div className="p-3 bg-slate-50 rounded-xl mb-4">
                    <div className="text-xs text-slate-500 mb-2 flex items-center gap-1">
                      <MessageCircle className="size-3" />
                      {t.passengerHistory.chatRecord.replace('{count}', String(selected.messages.length))}
                    </div>
                    <div className="space-y-2 max-h-40 overflow-y-auto">
                      {selected.messages.map((msg) => (
                        <div
                          key={msg.id}
                          className={`flex ${msg.from === 'passenger' ? 'justify-end' : 'justify-start'}`}
                        >
                          <div
                            className={`max-w-[80%] px-2.5 py-1.5 rounded-xl text-xs ${
                              msg.from === 'passenger'
                                ? 'bg-primary text-white rounded-br-sm'
                                : 'bg-white border border-slate-200 text-foreground rounded-bl-sm'
                            }`}
                          >
                            {msg.text}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                 <div className="text-center">
                     <Badge variant="outline" className="font-mono text-xs">
                       {t.passengerHistory.orderNo.replace('{id}', selected.id)}
                     </Badge>
                 </div>

                 {/* 收據按鈕（已付款先顯示） */}
                 {(selected.status === 'finished' || selected.status === 'paid' || selected.status === 'completed') && selected.receiptNo && (
                   <button
                     onClick={(e) => {
                       e.stopPropagation();
                       const fare = (selected.actualFare ?? selected.estimatedFare) - (selected.tip ?? 0);
                       setReceiptData({
                         receiptNo: selected.receiptNo!,
                         paidAt: selected.paidAt ?? selected.createdAt,
                         pickupName: selected.pickup?.name || '上車點',
                         destinationName: selected.destination?.name || '目的地',
                         fare,
                         tip: selected.tip ?? 0,
                         total: selected.actualFare ?? selected.estimatedFare,
                         paymentMethod: selected.paymentMethod || 'octopus',
                         carType: selected.carType,
                         plate: selected.driver?.plate,
                         driverName: selected.driver?.name,
                         distanceKm: selected.distanceKm ?? 3.5,
                         durationMin: 12,
                         orderId: selected.id,
                       });
                       setReceiptOpen(true);
                     }}
                     className="w-full mt-4 h-11 rounded-xl bg-slate-900 text-white text-sm font-semibold flex items-center justify-center gap-2 hover:bg-slate-800 transition-colors"
                   >
                      <FileText className="size-4" />
                      {t.passengerHistory.viewReceipt || '查看電子收據'}
                   </button>
                 )}

                 {/* 投訴記錄 */}
                 {selected.complaint && (
                   <div className="mt-4 p-3 bg-amber-50 border border-amber-200/50 rounded-xl">
                      <div className="text-xs font-bold text-amber-700 mb-1.5 flex items-center gap-1">
                        <MessageSquare className="size-3" />
                        {t.passengerHistory.complaintRecord || '投訴記錄'}
                        <Badge variant="outline" className="ml-auto text-[10px] border-amber-300 text-amber-600">
                          {selected.complaint.status === 'resolved'
                            ? (t.passengerHistory.complaintStatus?.resolved || '已處理')
                            : (t.passengerHistory.complaintStatus?.pending || '處理中')}
                        </Badge>
                      </div>
                      <div className="text-xs text-amber-700/80 mb-1">
                        {t.passengerHistory.complaintTypeLabel || '問題'}：
                        {(t.passengerRating.complaintTypes as Record<string, string>)[selected.complaint.type] || selected.complaint.type}
                      </div>
                     <div className="text-xs text-amber-800/70">{selected.complaint.description}</div>
                     {selected.complaint.reply && (
                       <div className="mt-2 pt-2 border-t border-amber-200/50">
                          <div className="text-[11px] font-medium text-emerald-700 mb-0.5">{t.passengerHistory.complaintReply || '處理回覆'}</div>
                         <div className="text-xs text-amber-800/70">{selected.complaint.reply}</div>
                       </div>
                     )}
                   </div>
                 )}
               </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
      {/* 電子收據彈窗 */}
      <ReceiptModal
        open={receiptOpen}
        onClose={() => setReceiptOpen(false)}
        data={receiptData}
      />
    </div>
  );
}
